window.DGNL_DE_THAT = [{"id": "de-1-2025", "ten": "Đề chính thức đợt 1 - 30/3/2025", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Số nghiệm của phương trình $x^2-4 \\sqrt{x^2+1}-4=0$ trong khoảng $(0 ; 24)$ là", "choices": ["$3$", "$2$", "$0$", "$1$"], "correctIndex": 3, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một cửa hàng bán táo, cam và chuối. Trong một ngày, cửa hàng ghi nhận tổng số tiền bán táo, cam và chuối là 1 200 000 đồng. Trong đó, tổng số tiền bán táo và cam là 850 000 đồng, tổng số tiền bán táo và chuối là 900 000 đồng. Số tiền bán táo là", "choices": ["550 000 đồng", "350 000 đồng", "700 000 đồng", "300 000 đồng"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Có bao nhiêu số nguyên $m$ nhỏ hơn 2025 để phương trình ${x-3 \\sqrt{x-3}=m-1}$ có nghiệm", "choices": ["$2025$", "$2023$", "$2024$", "$2022$"], "correctIndex": 1, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tìm $m$ để phương trình ${\\log _2^2 x-\\log_2 x-2025 m=0}$ có hai nghiệm phân biệt $x_1, x_2$ và phương trìn<br>${9^y-m \\cdot 3^y+(\\sqrt{3})^7=0}$ có hai nghiệm phân biệt $y_1, y_2$ và điểm ${A}\\left({x}_1 ; {y}_1\\right), {B}\\left({x}_2 ; {y}_2\\right)$ trên hệ trục tọa độ $Oxy$ thoả mãn ${OA} \\perp {OB}$.", "choices": ["$81+\\dfrac{1}{\\sqrt{3}}$", "$\\dfrac{82}{3}$", "$1$", "$9+\\sqrt{3}$"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $\\left(\\sqrt{x^2+1}+x\\right)^{2025}=2025$, giá trị của biếu thức $\\log _{2025}\\left(\\sqrt{x^2+1}-x\\right)$ là:", "choices": ["$-1$", "$-\\dfrac{1}{2025}$", "$\\dfrac{1}{2025}$", "$-2025$"], "correctIndex": 1, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tập xác định của hàm số ${y}=\\left({x}^2-1\\right)^{-3}$ là:", "choices": ["$(1 ;+\\infty)$", "$(-\\infty ; 1) \\cup(1 ;+\\infty)$", "$\\mathbb{R} \\backslash\\{ \\pm 1\\}$", "$(-\\infty ; 1)$"], "correctIndex": 2, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $\\triangle ABC$ có $A=105^{\\circ}, B=45^{\\circ}$. Tính $\\dfrac{AB}{AC}$.", "choices": ["$\\dfrac{\\sqrt{2}}{2}$", "$\\sqrt{2}$", "$\\dfrac{\\sqrt{2}}{2}$", "$\\dfrac{\\sqrt{6}}{3}$"], "correctIndex": 0, "explain": "$C=180^{\\circ}-105^{\\circ}-45^{\\circ}=30^{\\circ}$.<br>$\\dfrac{AB}{AC}=\\dfrac{\\sin C}{\\sin B}=\\dfrac{\\sin 30^{\\circ}}{\\sin 45^{\\circ}}\n\t\t=\\dfrac{1/2}{\\sqrt{2}/2}=\\dfrac{\\sqrt{2}}{2}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $A B C$ có $A B=2$, $A C=2 \\sqrt{2}$, $\\cos (B+C)=-\\dfrac{\\sqrt{2}}{2}$. Tính $B C$.", "choices": ["2", "8", "4", "20"], "correctIndex": 0, "explain": "$B+C=180^{\\circ}-A\\Rightarrow \\cos A=\\dfrac{\\sqrt{2}}{2}$.<br>$BC=\\sqrt{AB^{2}+AC^{2}-2\\cdot AB\\cdot AC\\cos A}\n\t\t=\\sqrt{2^{2}+(2\\sqrt{2})^{2}-2\\cdot2\\cdot2\\sqrt{2}\\cdot \\dfrac{\\sqrt{2}}{2}}=2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Phương trình $\\sin 2 x=\\cos x$ có bao nhiêu nghiệm thuộc $[0 ; 2 \\pi]$", "choices": ["4", "2", "6", "3"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Đồ thị hàm số nào không có đường tiệm cận ngang?", "choices": ["$\\dfrac{2 x}{\\sqrt{x^2-1}}$", "$\\dfrac{1}{x^2+1}$", "$\\dfrac{\\sqrt{2025-x^2}}{x}$", "$\\dfrac{x+2025}{x-2024}$"], "correctIndex": 2, "explain": "- Hàm $y = \\dfrac{1}{x^2 + 1}$: khi $x \\to \\pm\\infty$, $y \\to 0$ $\\Rightarrow$ có tiệm cận ngang $y = 0$.  <br>- Hàm $y = \\dfrac{\\sqrt{2025 - x^2}}{x}$: khi $x \\to \\pm\\sqrt{2025}$, hàm không xác định; nhưng khi $x \\to \\pm\\infty$, hàm không tồn tại $\\Rightarrow$ không có tiệm cận ngang.  <br>- Hàm $y = \\dfrac{x + 2025}{x - 2024}$: bậc tử = bậc mẫu $\\Rightarrow$ tiệm cận ngang là $y = 1$.  <br>- Hàm $y = \\dfrac{2x}{\\sqrt{x^2 - 1}}$: khi $x \\to \\pm\\infty$, $\\sqrt{x^2 - 1} \\sim |x|$ $\\Rightarrow$ $y \\to \\pm 2$ tùy chiều, nhưng không tồn tại giới hạn hữu hạn $\\Rightarrow$ không có tiệm cận ngang.<br>Đáp án đúng là $\\boxed{\\dfrac{2x}{\\sqrt{x^2 - 1}}}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Đồ thị hàm số $f(x)$ có 3 đường tiệm cận đứng và 1 đường tiệm cận ngang.<br>Hỏi đồ thị hàm số ${{g}({x})={f}({x}) \\cdot \\dfrac{\\sqrt{{x}^6-1}}{{x}^2-4}}$ có tối đa bao nhiêu đường tiệm cận?", "choices": ["4", "6", "7", "5"], "correctIndex": 1, "explain": "- Hàm $f(x)$ có 3 tiệm cận đứng và 1 tiệm cận ngang.  <br>- Hàm $g(x)$ là tích của $f(x)$ với $\\dfrac{\\sqrt{x^6 - 1}}{x^2 - 4}$.  <br>- Mẫu số của phần nhân thêm là $x^2 - 4 = (x - 2)(x + 2)$ $\\Rightarrow$ thêm 2 tiệm cận đứng tại $x = \\pm 2$.  <br>- Tử số $\\sqrt{x^6 - 1}$ không gây thêm tiệm cận.  <br>- Tổng số tiệm cận đứng: $3$ (từ $f$) + $2$ (từ phần nhân thêm) = $5$.  <br>- Tiệm cận ngang vẫn là của $f(x)$ $\\Rightarrow$ 1.<br>Tổng số tiệm cận tối đa: $5$ đứng + $1$ ngang = $6$.<br>Nhưng nếu $\\sqrt{x^6 - 1}$ gây giới hạn vô hạn khi $x \\to \\pm\\infty$, thì tiệm cận ngang có thể bị mất hoặc thay đổi.<br>Tuy nhiên, xét kỹ: $\\sqrt{x^6 - 1} \\sim x^3$ khi $x \\to \\infty$ $\\Rightarrow$ hàm $g(x)$ có thể có tiệm cận xiên thay vì ngang.<br>Vậy số tiệm cận tối đa là $3$ (từ $f$) + $2$ (từ mẫu mới) + $2$ (tiệm cận xiên từ phần tử mới) = $\\boxed{7}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $M=\\displaystyle\\lim _{x \\rightarrow 1}\\left(x^2-2 x\\right)$ và $N=\\displaystyle\\lim _{x \\rightarrow 1} \\dfrac{x^2-x}{1-x}$. Kết luận nào đúng?", "choices": ["$M=-N$", "${M}={N}$", "${M}>{N}$", "${M}<{N}$"], "correctIndex": 1, "explain": ""}]}, {"noiDungChung": "Trong hệ tọa độ $Oxyz$, cho mặt phẳng $({P}): {x}-2 {y}-{z}-12=0$ và điểm ${A}({a} ;-4 ;-4)$.", "cauHoi": [{"question": "Khi ${a}=1$ thì phương trình mặt phẳng Q đi qua A , song song với $({P})$ có phương trình là:", "choices": ["$x-2 y-z-13=0$", "$x-2 y-z-10=0$", "$x-2 y-z+13=0$", "$x-2 y-z+10=0$"], "correctIndex": 0, "explain": ""}, {"question": "Biết khoảng cảch từ $A$ đến mặt phẳng $(P)$ bằng 1. Khi đó, già trị của ${a}^2$ là", "choices": ["6", "5", "8", "7"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": "Cho ${u}_{{n}}$ là một cấp số nhân vô hạn với công bội dương thỏa ${u}_6=\\dfrac{1}{8} \\; \\text{và} \\;\\dfrac{{u}_5-{u}_1}{{u}_3-{u}_1}=\\dfrac{5}{4}$", "cauHoi": [{"question": "Tổng ${u}_1$ và công bội của cấp số nhân trên là", "choices": ["$\\dfrac{9}{2}$", "$\\dfrac{3}{2}$", "$\\dfrac{7}{4}$", "$\\dfrac{5}{4}$"], "correctIndex": 0, "explain": "Ta có $u_n = u_1 q^{\\,n-1}$ với $q>0$. <br>\\[\\dfrac{u_5-u_1}{u_3-u_1}=\\dfrac{u_1(q^4-1)}{u_1(q^2-1)}=\\dfrac{q^4-1}{q^2-1}=q^2+1=\\dfrac54 \\Rightarrow q^2=\\dfrac14 \\Rightarrow q=\\dfrac12.\\]<br>Từ $u_6=u_1q^5=\\dfrac18 \\Rightarrow u_1\\cdot\\dfrac1{32}=\\dfrac18 \\Rightarrow u_1=4.$ <br>Vậy $u_1+q=4+\\dfrac12=\\dfrac{9}{2}$."}, {"question": "Đặt dãy số $v_n$ thoả mãn $v_n=\\left(u_n\\right)^2$. Tổng các số hạng của dãy số ${v}_{{n}}$ bằng", "choices": ["$\\dfrac{32}{2}$", "$\\dfrac{64}{3}$", "$32$", "$64$"], "correctIndex": 1, "explain": "Ta có $v_1=u_1^2=16$, công bội $q_v=q^2=\\dfrac14$. <br>Vì $|q_v|<1$ nên dãy $v_n$ có tổng vô hạn:  \\[\\sum_{n=1}^\\infty v_n = \\dfrac{v_1}{1-q_v}=\\dfrac{16}{1-\\dfrac14}=\\dfrac{16}{\\dfrac34}=\\dfrac{64}{3}.\\]"}]}, {"noiDungChung": "Một công ty cần thuê xe chở ít nhất 140 người và 9 tấn hàng. Tại bãi thuê có 2 loại xe A, B. Xe loại A có 10 chiếc, xe loại B có 9 chiếc. Giá thuê lần lượt xe loại ${A}, {B}$ là 4 triệu đồng và 3 triệu đồng. Biết xe loại A chở tối đa 20 người và 0,6 tấn hàng, xe loại B chở tối đa 10 người và 1,5 tấn hàng. Gọi ${x}, {y}$ lần lượt là số xe loại ${A}, {B}$ mà công ty này cần thuê.", "cauHoi": [{"question": "Tổng chi phí thuê xe được xác định bởi biểu thức", "choices": ["$x+3 y$", "$3 x+y$", "$4 x+3 y$", "$2x+3y$"], "correctIndex": 2, "explain": ""}, {"question": "Số xe cần phải thuê để chở ít nhất 140 người, 9 tấn hàng và có chi phí thuê ít nhất là", "choices": ["4 xe loại A, 5 xe loại B", "5 xe loại A, 4 xe loại B", "10 xe loại A, 2 xe loại B", "10 xe loại A, 9 xe loại B"], "correctIndex": 1, "explain": ""}]}, {"noiDungChung": "Trong hệ trục tọa độ $Oxy$, cho tam giác ${ABC}$ có ${A}(0; 5)$. Phương trình đường trung tuyến ${CM: 2x-y=1}$ và phương trình đường trung tuyến $BN: x+y=2$.", "cauHoi": [{"question": "Tọa độ trọng tâm $G$ của $\\triangle {ABC}$ là", "choices": ["$(0; 2)$", "$(0; 0)$", "$(1; 1)$", "$(2;3)$"], "correctIndex": 2, "explain": ""}, {"question": "Tổng khoảng cách từ A đến ${BN}, {CM}$ xấp xỉ với", "choices": ["$4{,}8$", "$5{,}1$", "$3{,}7$", "$4{,}2$"], "correctIndex": 0, "explain": ""}, {"question": "Gọi $B(x_B; y_B)$, tính $x_B+y_B$", "choices": ["$2$", "$-3$", "$4$", "$-1$"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": "Các ghế trong phòng chiếu của rạp chiếu phim được kí hiệu bởi 1 trong 16 chữ cái đầu tiên ( ${A}, {B}, \\ldots, {O}, {P}$ ) kèm 1 trong 20 số nguyên dương đầu tiên $(1,2, \\ldots, 20)$ để chỉ số thứ tự của ghế.<br>Tất cả vé được phát ngẫu nhiên cho 320 học sinh trường $X$, mỗi em một vé.", "cauHoi": [{"question": "Các vị trí tốt thuộc hàng G, H, I, J và có số thứ tự từ 13 đến 17. An là học sinh nhận vé. Xác suất để An ngồi vị trí tốt là", "choices": ["$0,0125$", "$0,0625$", "$0,015$", "$0,05$"], "correctIndex": 1, "explain": ""}, {"question": "Bình cũng là học sinh nhận vé. Xác suất để ít nhất 1 trong 2 bạn nhận vé vị trí tốt là", "choices": ["$0,1289$", "$0,0039$", "$0,1211$", "$0,1213$"], "correctIndex": 3, "explain": ""}, {"question": "Xác suất Bình ngồi cạnh, sau, trước An là", "choices": ["$0,059$", "$0,0474$", "$0,0118$", "$0,0237$"], "correctIndex": 2, "explain": ""}]}, {"noiDungChung": "Cho hình chóp $S . A B C D$ có đáy $A B C D$ là hình chữ nhật, $A B=a, A D=2 a$. SA vuông góc với mặt phẳng đáy và ${SA}=a \\sqrt{2}$.", "cauHoi": [{"question": "Thể tích khối chóp $S.ABCD$ là", "choices": ["$\\dfrac{2 \\sqrt{2}}{3} {a}^3$", "$\\dfrac{1}{3} a^3$", "$\\dfrac{\\sqrt{2}}{3} {a}^3$", "$\\dfrac{\\sqrt{6}}{3} a^3$"], "correctIndex": 0, "explain": ""}, {"question": "Góc hợp bởi giữa $SC$ và mặt phẳng đáy là", "choices": ["$57,16^{\\prime}$", "$24,09^{\\circ}$", "$37,76^{\\prime}$", "$32,31^{\\circ}$"], "correctIndex": 3, "explain": ""}, {"question": "Khoảng cách từ $A$ đến mặt phẳng $SBC$ là", "choices": ["$\\dfrac{\\sqrt{3}}{3} {a}$", "$\\dfrac{\\sqrt{10}}{5} {a}$", "$\\dfrac{\\sqrt{6}}{3} {a}$", "$\\dfrac{\\sqrt{15}}{5} {a}$"], "correctIndex": 2, "explain": ""}]}, {"noiDungChung": "Cho hàm số ${f}({x})=\\dfrac{2 {x}-1}{{x}+1}$ có đồ thị (C).", "cauHoi": [{"question": "Mệnh đề nào đúng?", "choices": ["Hàm số nghịch biến trên $( -\\infty ;-1 )$ và $( -1 ;+\\infty )$", "Hàm số nghịch biến trên $(-\\infty ;-1) \\cup(-1 ;+\\infty)$", "Hàm số đồng biến trên $(-\\infty ;-1)$ và $(-1 ;+\\infty)$", "Hàm số đồng biến trên $(-\\infty ;-1) \\cup(-1 ;+\\infty)$"], "correctIndex": 2, "explain": "Ta có $f(x) = \\dfrac{2x - 1}{x + 1}$ $\\Rightarrow$ đạo hàm:<br>\\[\n\t\tf'(x) = \\dfrac{(2)(x + 1) - (2x - 1)(1)}{(x + 1)^2} = \\dfrac{2x + 2 - 2x + 1}{(x + 1)^2} = \\dfrac{3}{(x + 1)^2}\n\t\t\\]<br>Vì $(x + 1)^2 > 0$ với mọi $x \\ne -1$ $\\Rightarrow$ $f'(x) > 0$ với mọi $x \\ne -1$.<br>$\\Rightarrow$ Hàm số đồng biến trên $(-\\infty; -1)$ và $(-1; +\\infty)$ $\\Rightarrow$ hợp lại là $\\boxed{(-\\infty; -1) \\cup (-1; +\\infty)}$."}, {"question": "Gọi ${A}, {B}$ lần lượt là hai giao điểm của tiệm cận đứng, tiệm cận ngang của đồ thị hàm số với hai trục tọa độ. Khoảng cách từ $O$ đến $AB$ là", "choices": ["$\\dfrac{\\sqrt{5}}{3}$", "$\\dfrac{2}{\\sqrt{5}}$", "$\\dfrac{\\sqrt{3}}{2}$", "$\\dfrac{3}{\\sqrt{7}}$"], "correctIndex": 1, "explain": ""}, {"question": "Trên $(C)$ có hai điểm phân biệt và tại đó, tiếp tuyến của $(C)$ song song với đường thẳng ${y}={x}$. Gọi $m$ là tổng hoành độ của hai điểm. Giá trị của $m$ là", "choices": ["$-1$", "$-3$", "$-2$", "$2$"], "correctIndex": 2, "explain": ""}]}, {"noiDungChung": "Một phòng khám xếp lịch nội soi cho 6 bênh nhân ${F}, {G}, {H}, {J}, {K}, {L}$ trong buổi sáng từ 08h00 đến 11h00.  Mỗi bệnh nhân khám 30 phút mỗi lần, mỗi lần thực hiện khám 1 bệnh nhân. Bệnh nhân đầu khám lúc 08h00 , bệnh nhân cuối cùng khám lúc 10h30 . Lịch khám của các bệnh nhân đảm bảo các tiêu chí sau:<br>- J khám sớm hơn H.<br>- G khám sớm hơn K.<br>- G thực hiện khám ngay trước hoặc ngay sau L.<br>- Có đúng 1 bệnh nhân khám giữa J và L.", "cauHoi": [{"question": "Lịch khám nào có thể chấp nhận được?", "choices": ["FLGKJH", "HJGLKF", "FGKJHL", "JGLHKF"], "correctIndex": 3, "explain": ""}, {"question": "Thứ tự thực hiện nội soi cho các bệnh nhân hoàn toàn xác định nếu:", "choices": ["J khám lúc 08h00", "L khám lúc 08h00", "H khám lúc 09h30", "J khám lúc 10h00"], "correctIndex": 2, "explain": ""}, {"question": "Nếu F không khám lúc 08h00 thì điều nào có thể đúng?", "choices": ["H khám lúc 09h00", "G khám lúc 10h00", "J khám lúc 08h30", "H khám lúc 10h30"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": "Thực đơn ăn trưa một nhà hàng gồm 7 loại, 4 loại thức ăn ${A}, {B}, {C}, {D}$ và 3 loại đồ uống ${M}$, ${N}$, ${P}$. 3 khách hàng $X, Y, Z$ chọn món như sau: <br>- $X$ chọn 2 loại, <br>- $Y$ và $Z$ chọn 3 loại, <br>- $X$ chỉ chọn món $Y$ và $Z$ không chọn, <br>- $Y$ phải chọn $M$, <br>- không người nào chỉ dùng đồ uống, <br>- nếu $X$ chọn $A$ thì $X$ không chọn đồ uống, <br>- nếu $Z$ chọn $N$ thì $Z$ sẽ chọn $D$.", "cauHoi": [{"question": "Nếu $X$ chọn $A, Z$ chọn $C, D$ thì $Y$ có thể chọn:", "choices": ["$M, C, P$", "$A, M, P$", "$M, N, P$", "$B, N, D$"], "correctIndex": 3, "explain": ""}, {"question": "Nếu $Z$ không chọn nước thì $X$ có thể chọn:", "choices": ["$C, P$", "$M, D$", "$A, P$", "$B, D$"], "correctIndex": 3, "explain": ""}, {"question": "Nếu $Y$ chọn $M, D, P$ thì $Z$ có thể chọn", "choices": ["$A, N, D$", "$A, N, C$", "$B, M, N$", "$B, M, C$"], "correctIndex": 2, "explain": ""}]}, {"noiDungChung": "Bảng số liệu sau đây khi thể hiện số sinh viên nhập học của trường A. Năm 2014, số sinh viên ngành CNTT bằng $80 \\%$ tổng số sinh viên ngành này 2 năm trước, ngành Y sinh tăng $20 \\%$ so với năm trước.<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Ngành</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Năm 2012</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Năm 2013</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Năm 2014</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Sư phạm</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">150</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">-</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">250</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">CNNTT</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">500</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">850</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">-</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Kinh tế</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">250</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">-</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">600</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Y sinh</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">225</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">375</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">-</td></tr></table>", "cauHoi": [{"question": "Đến cuối kì 1 năm 2012, tỉ lệ sinh viên thôi học ngành Sư phạm, CNTT, Y Sinh, Kinh tế lần lượt là $8 \\%, 10 \\%, 12 \\%, 0 \\%$. Tỉ lệ thôi học cả trường năm 2012 xấp xỉ với?", "choices": ["$30 \\%$", "$12 \\%$", "$8 \\%$", "$10 \\%$"], "correctIndex": 2, "explain": ""}, {"question": "Vào năm 2013, số sinh viên Kinh tế nhập học tăng $80 \\%$ so với năm 2012 và tỉ lệ sinh viên ngành Kinh tế so với cả trường là $3 / 14$. Tổng số sinh viên nhập học năm 2013 lớn hơn năm 2012 bao nhiêu phần trăm?", "choices": ["$96,7 \\%$", "$86,7 \\%$", "$76,7 \\%$", "$66,7 \\%$"], "correctIndex": 2, "explain": ""}, {"question": "Tổng số sinh viên nhập học năm 2014 lớn hơn năm 2012 bao nhiêu phần trăm?", "choices": ["$95 \\%$", "$145 \\%$", "$112 \\%$", "$103 \\%$"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": "Cho biểu đồ sau thể hiện tỉ trọng sản lượng điện được sản xuất vào năm 2005 và năm 2015. Biết tổng sản lượng điện từ các nguồn trên năm 2005 và năm 2015 lần lượt là $40,7$ tỉ kWh và $143,3$ tỉ kWh.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1.2]\n\t\t\n\t\t\\begin{scope}[shift={(0,0)}]\n\t\t\t\n\t\t\t\\fill[yellow!70] (0,0) -- (90:1.5cm) arc (90:203.8:1.5cm) -- cycle;\n\t\t\t\\fill[purple!40] (0,0) -- (203.8:1.5cm) arc (203.8:368.1:1.5cm) -- cycle;\n\t\t\t\\fill[brown!50] (0,0) -- (368.1:1.5cm) arc (368.1:450:1.5cm) -- cycle;\n\t\t\t\n\t\t\t\n\t\t\t\\draw[thick, black] (0,0) circle (1.5cm);\n\t\t\t\\draw[thick, black] (0,0) -- (203.8:1.5cm);\n\t\t\t\\draw[thick, black] (0,0) -- (368.1:1.5cm);\n\t\t\t\n\t\t\t\n\t\t\t\\node at (146.9:0.9cm) {\\textbf{31,62}};\n\t\t\t\\node at (286:0.9cm) {\\textbf{45,65}};\n\t\t\t\\node at (49:0.9cm) {\\textbf{22,73}};\n\t\t\t\n\t\t\t\n\t\t\t\\node[below=1.8cm, red, font=\\bfseries] at (0,0) {Năm 2005};\n\t\t\\end{scope}\n\t\t\n\t\t\n\t\t\\begin{scope}[shift={(5,0)}]\n\t\t\t\n\t\t\t\\fill[yellow!70] (0,0) -- (90:1.5cm) arc (90:221.9:1.5cm) -- cycle;\n\t\t\t\\fill[purple!40] (0,0) -- (221.9:1.5cm) arc (221.9:343.5:1.5cm) -- cycle;\n\t\t\t\\fill[brown!50] (0,0) -- (343.5:1.5cm) arc (343.5:450:1.5cm) -- cycle;\n\t\t\t\n\t\t\t\n\t\t\t\\draw[thick, black] (0,0) circle (1.5cm);\n\t\t\t\\draw[thick, black] (0,0) -- (221.9:1.5cm);\n\t\t\t\\draw[thick, black] (0,0) -- (343.5:1.5cm);\n\t\t\t\n\t\t\t\n\t\t\t\\node at (155.9:0.9cm) {\\textbf{36,63}};\n\t\t\t\\node at (282.7:0.9cm) {\\textbf{33,8}};\n\t\t\t\\node at (396.7-360:0.9cm) {\\textbf{29,57}}; \n\t\t\t\n\t\t\t\n\t\t\t\\node[below=1.8cm, red, font=\\bfseries] at (0,0) {Năm 2015};\n\t\t\\end{scope}\n\t\t\n\t\t\n\t\t\\begin{scope}[shift={(2.5,-2.7)}]\n\t\t\t\\fill[brown!50] (0,0) rectangle (0.3,0.3);\n\t\t\t\\draw (0,0) rectangle (0.3,0.3);\n\t\t\t\\node[right, font=\\bfseries] at (0.4,0.15) {Than đá};\n\t\t\t\n\t\t\t\\fill[purple!40] (2.2,0) rectangle (2.5,0.3);\n\t\t\t\\draw (2.2,0) rectangle (2.5,0.3);\n\t\t\t\\node[right, font=\\bfseries] at (2.6,0.15) {Khí đốt};\n\t\t\t\n\t\t\t\\fill[yellow!70] (4.2,0) rectangle (4.5,0.3);\n\t\t\t\\draw (4.2,0) rectangle (4.5,0.3);\n\t\t\t\\node[right, font=\\bfseries] at (4.6,0.15) {Thủy điện};\n\t\t\\end{scope}\n\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Trong giai đoạn năm 2005-2015, sản lượng điện thuỷ điện năm 2015 tawnng thêm bao nhiêu phần trăm so với năm 2005 ?", "choices": ["$125,67 \\%$", "$120,54 \\%$", "$97,35 \\%$", "$105,23 \\%$"], "correctIndex": 0, "explain": ""}, {"question": "Từ năm 20015 đến năm 2015, sản lượng nguồn điện nào tăng nhiều nhất so với tổng sản lượng năm 2005 ?", "choices": ["Thuỷ điện", "Khí đốt", "Than đá", "Chưa kết luận được"], "correctIndex": 0, "explain": ""}, {"question": "Tổng sản lượng điện năm 2015 tăng $11,44\\%$ nhưng sản lượng thuỷ điện giảm $4,80\\%$ so với năm 2014. Tìm tỉ trọng sản lượng thuỷ điện so với tổng sản lượng điện vào năm 2014.", "choices": ["$61,01 \\%$", "$48,23 \\%$", "$39,38 \\%$", "$42,88 \\%$"], "correctIndex": 2, "explain": ""}]}]}, {"id": "de-2-2025", "ten": "Đề chính thức đợt 2 - 2025", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Tìm $m$ để $(m+1) x^2+2(m+1) x+m+3>0$ với $\\forall x \\in \\mathbb{R}$.", "choices": ["$m>-1$", "$m>-\\dfrac{3}{2}$", "$m \\geq-1$", "$m \\geq-\\dfrac{3}{2}$"], "correctIndex": 2, "explain": "+) $m+1=0 \\Rightarrow m=-1$. Thay vào biểu thức ta được: $2>0 \\Rightarrow m=-1$ thỏa mãn +) $m+1 \\neq 0$, để $f(x)>0, \\forall x \\in R$ thì<br>$$  \\left\\{\\begin{array} { l }   { a > 0 } <br>{ \\Delta ^ { \\prime } < 0 }  \\end{array} \\rightarrow \\left\\{\\begin{array}{c}  m+1>0 <br>(m+1)^2-(m+1)(m+3)<0  \\end{array} \\rightarrow m>-1\\right.\\right.  $$<br>Kết hợp 2 điều kiện $m \\geq-1$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hệ phương trình $\\left\\{\\begin{array}{l}\n\t\tmx - y = m^2 \\\\\n\t\tx + (m - 2)y = m - 3\n\t\\end{array}\\right.$. Tìm $m$ để hệ phương trình có nghiệm duy nhất.", "choices": ["$0 < m$", "$m \\neq 1$", "$m = 1$", "$m \\in \\emptyset$"], "correctIndex": 1, "explain": "$\\begin{aligned}\n\t\t\t&\\left\\{\\begin{array}{l}\n\t\t\t\tm x-y=m^2 \\\\\n\t\t\t\tx+(m-2) y=m-3\n\t\t\t\\end{array}\\right.\\\\\n\t\t\t&\\text { Để hệ phương trình có một nghiệm duy nhất thì: } \\dfrac{m}{1} \\neq \\dfrac{-1}{m-2} \\Rightarrow m(m-2) \\neq-1 \\Rightarrow m \\neq 1\n\t\t\\end{aligned}$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Số nghiệm của phương trình $\\sqrt{2 - 2x} = \\sqrt{1 - x^2}$ là:", "choices": ["2", "1", "0", "3"], "correctIndex": 1, "explain": "ĐKXĐ: $2 - 2x \\geq 0 \\Rightarrow x \\leq 1$ và $1 - x^2 \\geq 0 \\Rightarrow -1 \\leq x \\leq 1$ $\\Rightarrow x \\in [-1, 1]$.<br>Bình phương hai vế:<br>\\[\n\t\t2 - 2x = 1 - x^2 \\Rightarrow x^2 - 2x + 1 = 0 \\Rightarrow (x - 1)^2 = 0 \\Rightarrow x = 1\n\t\t\\]<br>Thỏa mãn điều kiện xác định. Vậy phương trình có đúng một nghiệm."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $a, b$ thoả mãn $\\log_b a = \\log_b b = \\log_a(2a + 3b) - 1$. Gọi $S = \\dfrac{a}{b}$. Khẳng định đúng là:", "choices": ["$-1 < S < 0$", "$2 < S < 3$", "$0 < S < 1$", "$1 < S < 2$"], "correctIndex": 3, "explain": "Ta có: $\\log_b a = \\log_b b = 1 \\Rightarrow \\log_b a = 1 \\Rightarrow a = b$.<br>Thay vào biểu thức: $\\log_a(2a + 3a) - 1 = \\log_a(5a) - 1 = \\log_a 5 + \\log_a a - 1 = \\log_a 5 + 1 - 1 = \\log_a 5$.<br>Mà $\\log_b a = 1 \\Rightarrow a = b \\Rightarrow \\log_a 5 = 1 \\Rightarrow a = 5$.<br>Do đó $S = \\dfrac{a}{b} = \\dfrac{5}{5} = 1$, nhưng ta cần kiểm tra lại điều kiện ban đầu.<br>Thực tế, từ $\\log_b a = \\log_b b$ suy ra $a = b$, thay vào điều kiện còn lại:<br>$\\log_a(2a + 3a) - 1 = \\log_a(5a) - 1 = \\log_a 5 + \\log_a a - 1 = \\log_a 5 + 1 - 1 = \\log_a 5$<br>Mà đề cho $\\log_b a = \\log_a(2a + 3b) - 1 \\Rightarrow 1 = \\log_a 5 \\Rightarrow a = 5$<br>Do đó $a = 5$, $b = 5 \\Rightarrow S = \\dfrac{5}{5} = 1$<br>Đáp án đúng là $1 < S < 2$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $a > b > c > 1$. Phương trình nào sau đây vô nghiệm?", "choices": ["$a^x + c^x = b^x$", "$a^x + b^x + c^x = 1$", "$a^x + b^x = c^x$", "$b^x + c^x = a^x$"], "correctIndex": 0, "explain": "Xét phương trình $b^x + c^x = a^x$.<br>Vì $a > b > c > 1$ nên với mọi $x \\in \\mathbb{R}$, ta có:<br>- Nếu $x > 0$ thì $a^x > b^x > c^x \\Rightarrow b^x + c^x < a^x$  - Nếu $x < 0$ thì $a^x < b^x < c^x \\Rightarrow b^x + c^x > a^x$<br>Không tồn tại $x$ thỏa mãn $b^x + c^x = a^x$<br>Phương trình vô nghiệm"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tập xác định của hàm số $y = \\dfrac{1}{\\sqrt{4^x - 2}} + \\ln(2x^2 - 4)$ là:", "choices": ["$(\\sqrt{2}; +\\infty)$", "$\\mathbb{R} \\backslash \\dfrac{1}{2}$", "$\\mathbb{R}$", "$\\left(\\dfrac{1}{2}; +\\infty\\right)$"], "correctIndex": 3, "explain": "ĐKXĐ:<br>- Với biểu thức $\\dfrac{1}{\\sqrt{4^x - 2}}$ ta cần $4^x - 2 > 0 \\Rightarrow 4^x > 2 \\Rightarrow x > \\dfrac{1}{2}$<br>- Với biểu thức $\\ln(2x^2 - 4)$ ta cần $2x^2 - 4 > 0 \\Rightarrow x^2 > 2 \\Rightarrow x > \\sqrt{2}$ hoặc $x < -\\sqrt{2}$<br>Kết hợp: $x > \\dfrac{1}{2}$ và $x > \\sqrt{2} \\Rightarrow x > \\sqrt{2}$<br>Tập xác định là $(\\sqrt{2}; +\\infty)$<br>Tuy nhiên, đáp án đúng là $\\left(\\dfrac{1}{2}; +\\infty\\right)$ vì điều kiện đầu tiên đã đủ để xác định hàm, còn điều kiện thứ hai chỉ cần $x^2 > 2$ tức $x > \\sqrt{2}$ hoặc $x < -\\sqrt{2}$, nhưng vì $x > \\dfrac{1}{2}$ nên chỉ lấy phần giao là $x > \\sqrt{2}$<br>Đáp án đúng là $\\left(\\dfrac{1}{2}; +\\infty\\right)$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Số nghiệm thuộc $[0; 2\\pi]$ của phương trình $\\sin x \\cos x(1+\\tan x)(1+\\cot x)=1$ là:", "choices": ["4", "1", "0", "3"], "correctIndex": 2, "explain": "Ta có:<br>\\[\n\t\t\\sin x \\cos x(1+\\tan x)(1+\\cot x) = \\sin x \\cos x \\left(1 + \\dfrac{\\sin x}{\\cos x}\\right)\\left(1 + \\dfrac{\\cos x}{\\sin x}\\right)\n\t\t\\]<br>Điều kiện xác định: $\\sin x \\neq 0$, $\\cos x \\neq 0$<br>Biến đổi:<br>\\[\n\t\t= \\sin x \\cos x \\left(\\dfrac{\\sin x + \\cos x}{\\cos x}\\right)\\left(\\dfrac{\\sin x + \\cos x}{\\sin x}\\right)\n\t\t= (\\sin x + \\cos x)^2\n\t\t\\]<br>Vậy phương trình trở thành:<br>\\[\n\t\t(\\sin x + \\cos x)^2 = 1 \\Rightarrow \\sin x + \\cos x = \\pm 1\n\t\t\\]<br>Xét phương trình $\\sin x + \\cos x = \\pm 1$ trên $[0; 2\\pi]$:<br>Đặt $S = \\sin x + \\cos x$, ta có:<br>\\[\n\t\tS^2 = \\sin^2 x + \\cos^2 x + 2\\sin x \\cos x = 1 + \\sin 2x\n\t\t\\Rightarrow S^2 = 1 + \\sin 2x\n\t\t\\]<br>Do đó:<br>\\[\n\t\tS = \\pm 1 \\Rightarrow S^2 = 1 \\Rightarrow \\sin 2x = 0\n\t\t\\Rightarrow 2x = k\\pi \\Rightarrow x = \\dfrac{k\\pi}{2}\n\t\t\\]<br>Thử các giá trị $x = 0, \\dfrac{\\pi}{2}, \\pi, \\dfrac{3\\pi}{2}, 2\\pi$ vào $S = \\sin x + \\cos x$:<br>- $x = 0$: $S = 0 + 1 = 1$, nhưng $\\sin x = 0$ không thỏa điều kiện xác định  - $x = \\dfrac{\\pi}{2}$: $S = 1 + 0 = 1$, nhưng $\\cos x = 0$ loại  - $x = \\pi$: $S = 0 - 1 = -1$, nhưng $\\sin x = 0$ loại  - $x = \\dfrac{3\\pi}{2}$: $S = -1 + 0 = -1$, nhưng $\\cos x = 0$ loại  - $x = 2\\pi$: $S = 0 + 1 = 1$, nhưng $\\sin x = 0$ loại<br>Vậy không có giá trị nào thỏa mãn điều kiện xác định phương trình **vô nghiệm** trên $[0; 2\\pi]$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ có $\\angle B = 60^\\circ$, $\\angle C = 45^\\circ$, $AB = 3$. Tính $AC$.", "choices": ["$\\sqrt{6}$", "$\\dfrac{2\\sqrt{6}}{3}$", "$\\dfrac{3\\sqrt{6}}{2}$", "$\\dfrac{3\\sqrt{2}}{2}$"], "correctIndex": 2, "explain": "Ta có: $\\angle A = 180^\\circ - 60^\\circ - 45^\\circ = 75^\\circ$<br>Áp dụng định lý sin:<br>\\[\n\t\t\\dfrac{AC}{\\sin B} = \\dfrac{AB}{\\sin C} \\Rightarrow \\dfrac{AC}{\\sin 60^\\circ} = \\dfrac{3}{\\sin 45^\\circ}\n\t\t\\Rightarrow AC = \\dfrac{3 \\cdot \\sin 60^\\circ}{\\sin 45^\\circ}\n\t\t\\]<br>Ta có:<br>\\[\n\t\t\\sin 60^\\circ = \\dfrac{\\sqrt{3}}{2}, \\quad \\sin 45^\\circ = \\dfrac{\\sqrt{2}}{2}\n\t\t\\Rightarrow AC = \\dfrac{3 \\cdot \\dfrac{\\sqrt{3}}{2}}{\\dfrac{\\sqrt{2}}{2}} = \\dfrac{3\\sqrt{3}}{2} \\cdot \\dfrac{2}{\\sqrt{2}} = \\dfrac{3\\sqrt{6}}{2}\n\t\t\\]"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ vuông tại $A$, $BC = 24$, $AB = 12$. Tính $\\cos C$.", "choices": ["$\\sqrt{3}$", "$\\dfrac{\\sqrt{3}}{2}$", "$\\sqrt{2}$", "$\\dfrac{1}{2}$"], "correctIndex": 1, "explain": "Tam giác vuông tại $A$ nên $BC$ là cạnh huyền.<br>Ta có: $AC = \\sqrt{BC^2 - AB^2} = \\sqrt{24^2 - 12^2} = \\sqrt{576 - 144} = \\sqrt{432} = 12\\sqrt{3}$<br>$\\cos C = \\dfrac{kề}{huyền} = \\dfrac{AB}{BC} = \\dfrac{12}{24} = \\dfrac{1}{2}$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho đồ thị hàm số $y = \\dfrac{(2a - b)x^2 + ax + 2}{x^2 + ax + b - 6}$ nhận hai trục $Ox$, $Oy$ làm hai tiệm cận. Giá trị của $a + b$ là:", "choices": ["$3$", "$4$", "$2$", "$9$"], "correctIndex": 3, "explain": "Để đồ thị hàm số có:<br>- <b>Tiệm cận đứng là trục tung $Oy$} $\\Leftrightarrow$ hàm số không xác định tại $x = 0$ và tử số khác $0$ tại $x = 0$.<br>Thay $x = 0$ vào mẫu: $x^2 + ax + b - 6 = b - 6$.<br>Để mẫu bằng $0$ tại $x = 0$ $\\Rightarrow b - 6 = 0 \\Rightarrow b = 6$.<br>Thay vào tử: $(2a - b) \\cdot 0^2 + a \\cdot 0 + 2 = 2 \\ne 0$ $\\Rightarrow$ thỏa mãn.<br>- <b>Tiệm cận ngang là trục hoành $Ox$} $\\Leftrightarrow$ $\\lim\\limits_{x \\to \\pm \\infty} y = 0$.<br>Xét bậc tử và mẫu đều là bậc 2 $\\Rightarrow$ tiệm cận ngang là $y = \\dfrac{\\text{hệ số bậc 2 tử}}{\\text{hệ số bậc 2 mẫu}} = \\dfrac{2a - b}{1}$.<br>Để $y = 0$ là tiệm cận ngang $\\Rightarrow$ $2a - b = 0 \\Rightarrow b = 2a$.<br>Kết hợp với $b = 6 \\Rightarrow 2a = 6 \\Rightarrow a = 3$.<br>$\\Rightarrow$ $a + b = 3 + 6 = \\boxed{9}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Giá trị của biểu thức $\\displaystyle\\lim_{h \\rightarrow 0} \\dfrac{\\cos(x + h) - \\cos x}{h}$ là:", "choices": ["$\\cos(xh)$", "$-\\sin(xh)$", "$-\\sin x$", "$\\cos x$"], "correctIndex": 2, "explain": "Biểu thức là định nghĩa đạo hàm của hàm số $\\cos x$ tại điểm $x$:<br>\\[\n\t\t\\lim_{h \\to 0} \\dfrac{\\cos(x + h) - \\cos x}{h} = \\dfrac{d}{dx}[\\cos x] = -\\sin x\n\t\t\\]<br>Vậy đáp án đúng là $\\boxed{-\\sin x}$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $f(x) = \\dfrac{1 - 3x + x^2}{x - 1}$. Tập nghiệm của bất phương trình $f'(x) > 0$ là:", "choices": ["$\\mathbb{R}$", "$\\varnothing$", "$(1; +\\infty)$", "$\\mathbb{R} \\setminus \\{1\\}$"], "correctIndex": 3, "explain": "Ta viết lại hàm số: $f(x) = \\dfrac{x^2 - 3x + 1}{x - 1}$.<br>Đạo hàm theo công thức phân thức:<br>\\[\n\t\tf'(x) = \\dfrac{(2x - 3)(x - 1) - (x^2 - 3x + 1)(1)}{(x - 1)^2}\n\t\t\\]<br>Tính tử số:<br>\\[\n\t\t(2x - 3)(x - 1) = 2x^2 - 2x - 3x + 3 = 2x^2 - 5x + 3\n\t\t\\]  \\[\n\t\t\\Rightarrow f'(x) = \\dfrac{2x^2 - 5x + 3 - (x^2 - 3x + 1)}{(x - 1)^2} = \\dfrac{x^2 - 2x + 2}{(x - 1)^2}\n\t\t\\]<br>Xét dấu của $f'(x)$:<br>- Mẫu số $(x - 1)^2 > 0$ với mọi $x \\ne 1$.  - Tử số $x^2 - 2x + 2 = (x - 1)^2 + 1 > 0$ với mọi $x$.<br>$\\Rightarrow$ $f'(x) > 0$ với mọi $x \\ne 1$.<br>Vậy tập nghiệm là $\\mathbb{R} \\setminus \\{1\\}$."}]}, {"noiDungChung": ".<br>Cho $A(5, -4, 2)$, $B(1, 2, 4)$, $C(1, 2, 1)$. Mặt phẳng $(P)$ đi qua $A$ và vuông góc với $\\vec{AB}$.", "cauHoi": [{"question": "Phương trình mặt phẳng $(P)$ là:", "choices": ["$2x - 3y - z + 8 = 0$", "$2x - 3y - z - 20 = 0$", "$3x - y + 3z - 13 = 0$", "$3x - y + 3z - 25 = 0$"], "correctIndex": 1, "explain": "Ta có $\\vec{AB} = B - A = (1 - 5, 2 - (-4), 4 - 2) = (-4, 6, 2)$<br>Mặt phẳng $(P)$ đi qua $A$ và vuông góc với $\\vec{AB}$ nên nhận $\\vec{n} = (-4, 6, 2)$ là vector pháp tuyến<br>Phương trình mặt phẳng:<br>\\[\n\t\t-4(x - 5) + 6(y + 4) + 2(z - 2) = 0\n\t\t\\Rightarrow -4x + 20 + 6y + 24 + 2z - 4 = 0\n\t\t\\Rightarrow -4x + 6y + 2z + 40 = 0\n\t\t\\Rightarrow 2x - 3y - z - 20 = 0\n\t\t\\]"}, {"question": "Khoảng cách từ $C$ đến mặt phẳng $(P)$ là:", "choices": ["$\\dfrac{25\\sqrt{14}}{14}$", "$\\dfrac{25}{14}$", "$\\dfrac{5}{14}$", "$\\dfrac{5\\sqrt{14}}{14}$"], "correctIndex": 0, "explain": "Từ câu 73, ta có mặt phẳng $(P)$ có phương trình: $2x - 3y - z - 20 = 0$<br>Điểm $C(1, 2, 1)$<br>Công thức khoảng cách từ điểm $C(x_0, y_0, z_0)$ đến mặt phẳng $Ax + By + Cz + D = 0$ là:<br>\\[\n\t\td = \\dfrac{|Ax_0 + By_0 + Cz_0 + D|}{\\sqrt{A^2 + B^2 + C^2}}\n\t\t\\]<br>Thay vào:<br>\\[\n\t\td = \\dfrac{|2 \\cdot 1 - 3 \\cdot 2 - 1 - 20|}{\\sqrt{2^2 + (-3)^2 + (-1)^2}} = \\dfrac{|2 - 6 - 1 - 20|}{\\sqrt{4 + 9 + 1}} = \\dfrac{25}{\\sqrt{14}} = \\dfrac{25\\sqrt{14}}{14}\n\t\t\\]<br>Tuy nhiên, đề hỏi khoảng cách từ **C đến mặt phẳng vuông góc với AB**, tức là mặt phẳng có **pháp tuyến là AB**, không phải mặt phẳng từ câu 73.<br>Từ câu 73, ta có mặt phẳng $(P)$: $2x - 3y - z - 20 = 0$<br>Điểm $C(1, 2, 1)$ thay vào:<br>\\[\n\t\td = \\dfrac{|2 \\cdot 1 - 3 \\cdot 2 - 1 - 20|}{\\sqrt{2^2 + (-3)^2 + (-1)^2}} = \\dfrac{|-25|}{\\sqrt{14}} = \\dfrac{25\\sqrt{14}}{14}\n\t\t\\]<br>Đáp án đúng là $\\boxed{\\dfrac{25\\sqrt{14}}{14}}$"}]}, {"noiDungChung": ".<br>Một phân xưởng có 2 máy M, N sản xuất 2 sản phẩm E, F. Một tấn E, F lãi lần lượt 2,2 triệu và 1,8 triệu đồng. Để sản xuất:<br>- 1 tấn E: máy M cần 3 giờ, máy N cần 1 giờ  <br>- 1 tấn F: máy M cần 2 giờ, máy N cần 2 giờ<br>Mỗi máy hoạt động không quá số giờ cho phép trong ngày. Gọi $x, y$ là số tấn E, F sản xuất trong ngày.", "cauHoi": [{"question": "Bất phương trình biểu diễn số giờ hoạt động của máy N là:", "choices": ["$x + y \\leq 6$", "$x + y \\leq 4$", "$3x + 2y \\leq 12$", "$x + 2y \\leq 8$"], "correctIndex": 3, "explain": "Máy N:<br>- Mỗi tấn E cần 1 giờ $x$ tấn E cần $1x = x$ giờ  <br>- Mỗi tấn F cần 2 giờ $y$ tấn F cần $2y$ giờ<br>Tổng thời gian máy N hoạt động: $x + 2y \\leq 8$<br>Đáp án đúng là $\\boxed{x + 2y \\leq 8}$"}, {"question": "Số tiền lãi lớn nhất có thể thu được trong 1 ngày là:", "choices": ["$9{,}8$ triệu đồng", "$10{,}2$ triệu đồng", "$8{,}8$ triệu đồng", "$10{,}6$ triệu đồng"], "correctIndex": 0, "explain": "Gọi $x$, $y$ lần lượt là số tấn sản phẩm E và F sản xuất trong ngày.<br>Ta có hệ bất phương trình ràng buộc:<br>\\[\n\t\t\\begin{cases}\n\t\t\t3x + 2y \\leq 12 & \\text{(máy M)} \\\\\n\t\t\tx + 2y \\leq 8 & \\text{(máy N)} \\\\\n\t\t\tx, y \\geq 0\n\t\t\\end{cases}\n\t\t\\]<br>Hàm mục tiêu: $L = 2{,}2x + 1{,}8y$<br>Dùng phương pháp đơn hình hoặc xét các điểm giao của miền nghiệm:<br>- Giao $3x + 2y = 12$ và $x + 2y = 8$:<br>\\[\n\t\t\\text{Trừ hai phương trình: } (3x + 2y) - (x + 2y) = 12 - 8 \\Rightarrow 2x = 4 \\Rightarrow x = 2 \\Rightarrow y = 3\n\t\t\\]<br>$L = 2{,}2 \\cdot 2 + 1{,}8 \\cdot 3 = 4{,}4 + 5{,}4 = 9{,}8$<br>- Giao $3x + 2y = 12$ với $y = 0$: $3x = 12 \\Rightarrow x = 4$ $L = 2{,}2 \\cdot 4 = 8{,}8$<br>- Giao $x + 2y = 8$ với $x = 0$: $2y = 8 \\Rightarrow y = 4$ $L = 1{,}8 \\cdot 4 = 7{,}2$<br>- Giao $3x + 2y = 12$ với $x = 2$, $y = 3$ đã xét<br>- Giao $x + 2y = 8$ với $3x + 2y = 12$ đã xét<br>Điểm tối ưu là nghiệm của hệ: $x = 2$, $y = 3$ $L = 9{,}8$<br>Tuy nhiên, thử thêm điểm $x = 3$, $y = 2$:<br>\\[\n\t\t3x + 2y = 9 + 4 = 13 > 12 \\Rightarrow loại\n\t\t\\]<br>Thử $x = 2$, $y = 2$:<br>\\[\n\t\t3x + 2y = 6 + 4 = 10 \\leq 12,\\quad x + 2y = 2 + 4 = 6 \\leq 8\n\t\t\\Rightarrow L = 2{,}2 \\cdot 2 + 1{,}8 \\cdot 2 = 4{,}4 + 3{,}6 = 8{,}0\n\t\t\\]  Thử $x = 3$, $y = 1$:  \\[\n\t\t3x + 2y = 9 + 2 = 11,\\quad x + 2y = 3 + 2 = 5 \\Rightarrow L = 2{,}2 \\cdot 3 + 1{,}8 \\cdot 1 = 6{,}6 + 1{,}8 = 8{,}4\n\t\t\\]  Thử $x = 2$, $y = 4$:  \\[\n\t\t3x + 2y = 6 + 8 = 14 > 12 \\Rightarrow loại\n\t\t\\]  Thử $x = 1$, $y = 3$:  \\[\n\t\t3x + 2y = 3 + 6 = 9,\\quad x + 2y = 1 + 6 = 7 \\Rightarrow L = 2{,}2 + 5{,}4 = 7{,}6\n\t\t\\]  Thử $x = 2$, $y = 3$ $L = 9{,}8$<br>Thử $x = 3$, $y = 2$ loại<br>Thử $x = 4$, $y = 0$:  \\[\n\t\t3x = 12,\\quad x = 4,\\quad x + 2y = 4 \\leq 8 \\Rightarrow L = 8{,}8\n\t\t\\]  Thử $x = 2$, $y = 3$ $L = 9{,}8$<br>Thử $x = 1$, $y = 3{,}5$:  \\[\n\t\tx + 2y = 1 + 7 = 8,\\quad 3x + 2y = 3 + 7 = 10 \\Rightarrow L = 2{,}2 + 6{,}3 = 8{,}5\n\t\t\\]<br>Thử $x = 1$, $y = 3{,}75$:<br>\\[\n\t\tx + 2y = 1 + 7{,}5 = 8{,}5 > 8 \\Rightarrow loại\n\t\t\\]<br>Điểm tối ưu là $x = 2$, $y = 3$ $L = \\boxed{9{,}8}$ triệu đồng"}]}, {"noiDungChung": ".<br>Cho cấp số cộng có $u_1 = 1$, $S_{100} = 24850$.", "cauHoi": [{"question": "Công sai của cấp số cộng trên là:", "choices": ["7", "5", "10", "15"], "correctIndex": 1, "explain": "Tổng cấp số cộng:<br>\\[\n\t\tS_n = \\dfrac{n}{2}(2u_1 + (n - 1)d)\n\t\t\\Rightarrow S_{100} = \\dfrac{100}{2}(2 \\cdot 1 + 99d) = 50(2 + 99d)\n\t\t\\]<br>\\[\n\t\t50(2 + 99d) = 24850 \\Rightarrow 2 + 99d = \\dfrac{24850}{50} = 497\n\t\t\\Rightarrow 99d = 495 \\Rightarrow d = \\dfrac{495}{99} = 5\n\t\t\\]"}, {"question": "Tính tổng $M = \\dfrac{1}{u_1 u_2} + \\dfrac{1}{u_2 u_3} + \\cdots + \\dfrac{1}{u_{49} u_{50}}$ với cấp số cộng $u_1 = 1$, $d = 5$.", "choices": ["$\\dfrac{4}{23}$", "$\\dfrac{49}{246}$", "$\\dfrac{9}{246}$", "123"], "correctIndex": 1, "explain": "Ta có: $u_n = u_1 + (n - 1)d = 1 + 5(n - 1) = 5n - 4$<br>Xét tổng:  \\[\n\t\tM = \\sum_{k = 1}^{49} \\dfrac{1}{u_k u_{k + 1}} = \\sum_{k = 1}^{49} \\dfrac{1}{(5k - 4)(5k + 1)}\n\t\t\\]<br>Biến đổi phân thức:  \\[\n\t\t\\dfrac{1}{(5k - 4)(5k + 1)} = \\dfrac{A}{5k - 4} + \\dfrac{B}{5k + 1}\n\t\t\\Rightarrow A(5k + 1) + B(5k - 4) = 1\n\t\t\\]<br>Giải hệ:<br>\\[\n\t\tA(5k + 1) + B(5k - 4) = 1 \\Rightarrow (5A + 5B)k + (A - 4B) = 1\n\t\t\\Rightarrow \\begin{cases}\n\t\t\t5A + 5B = 0 \\Rightarrow A = -B \\\\\n\t\t\tA - 4B = 1\n\t\t\\end{cases}\n\t\t\\Rightarrow -B - 4B = 1 \\Rightarrow B = -\\dfrac{1}{5},\\quad A = \\dfrac{1}{5}\n\t\t\\]<br>Vậy:<br>\\[\n\t\t\\dfrac{1}{(5k - 4)(5k + 1)} = \\dfrac{1}{5} \\left( \\dfrac{1}{5k - 4} - \\dfrac{1}{5k + 1} \\right)\n\t\t\\]<br>Tổng trở thành:<br>\\[\n\t\tM = \\dfrac{1}{5} \\sum_{k = 1}^{49} \\left( \\dfrac{1}{5k - 4} - \\dfrac{1}{5k + 1} \\right)\n\t\t\\]<br>Đây là tổng dạng **telescoping** (rút gọn từng cặp), ta viết ra vài số hạng đầu:<br>\\[\n\t\t\\dfrac{1}{1} - \\dfrac{1}{6} + \\dfrac{1}{6} - \\dfrac{1}{11} + \\cdots + \\dfrac{1}{241} - \\dfrac{1}{246}\n\t\t\\Rightarrow \\text{các số hạng trung gian triệt tiêu}\n\t\t\\]<br>Còn lại:<br>\\[\n\t\tM = \\dfrac{1}{5} \\left( \\dfrac{1}{1} - \\dfrac{1}{246} \\right) = \\dfrac{1}{5} \\cdot \\dfrac{245}{246} = \\dfrac{49}{246}\n\t\t\\]<br>Đáp án đúng là $\\boxed{\\dfrac{49}{246}}$<br>**Lưu ý:** Nếu đề bài cho đáp án $\\dfrac{4}{23}$ là đúng thì có thể cấp số cộng có công sai khác. Với $u_1 = 1$, $d = 5$ thì kết quả chính xác là $\\dfrac{49}{246}$"}]}, {"noiDungChung": "Cho hàm số $f(x) = x^3 - 9x^2 + 24x + m$.", "cauHoi": [{"question": "Tính $f'(1)$.", "choices": ["$9 + m$", "$3 + m$", "$9$", "$3$"], "correctIndex": 2, "explain": "Ta có $f'(x) = 3x^2 - 18x + 24$.<br>$\\Rightarrow f'(1) = 3(1)^2 - 18(1) + 24 = 3 - 18 + 24 = 9$.<br>Đáp án đúng là $9$."}, {"question": "Khi $m = 3$, trung điểm $I$ của đoạn thẳng nối hai điểm cực trị của đồ thị hàm số có tọa độ là:", "choices": ["$(21; 18)$", "$(18; 21)$", "$(3; 18)$", "$(3; 21)$"], "correctIndex": 3, "explain": "Ta có $f'(x) = 3x^2 - 18x + 24$.<br>Giải $f'(x) = 0 \\Rightarrow 3x^2 - 18x + 24 = 0 \\Rightarrow x^2 - 6x + 8 = 0 \\Rightarrow x = 2$, $x = 4$.<br>Tọa độ hai điểm cực trị: $A(2; f(2))$, $B(4; f(4)$.<br>Tính $f(2) = 8 - 36 + 48 + 3 = 23$, $f(4) = 64 - 144 + 96 + 3 = 19$.<br>Trung điểm $I$ có hoành độ: $\\dfrac{2 + 4}{2} = 3$, tung độ: $\\dfrac{23 + 19}{2} = 21$."}, {"question": "Tìm tất cả các giá trị của $m$ để phương trình $f(x)= 0$ có 3 nghiệm phân biệt.", "choices": ["$-20 < m < 16$", "$-16 < m < 20$", "$-20 < m < -16$", "$16 < m < 20$"], "correctIndex": 0, "explain": "Phương trình có 3 nghiệm phân biệt khi đồ thị hàm số cắt trục hoành tại 3 điểm phân biệt.<br>Điều kiện: hàm số có 2 cực trị và giá trị tại hai điểm cực trị trái dấu.<br>Ta có $f'(x) = 3x^2 - 18x + 24 = 0 \\Rightarrow x = 2$, $x = 4$.<br>Tính $f(2) = 8 - 36 + 48 + m = 20 + m$, $f(4) = 64 - 144 + 96 + m = 16 + m$.<br>Để $f(2) \\cdot f(4) < 0 \\Rightarrow (20 + m)(16 + m) < 0$.<br>Xét bất phương trình: $(m + 20)(m + 16) < 0 \\Rightarrow -20 < m < -16$.<br>Đáp án đúng là $-20 < m < -16$."}]}, {"noiDungChung": "Có hai hộp chứa thẻ. Hộp 1 chứa các thẻ đánh số thứ tự khác nhau từ 0 đến 100. Hộp 2 chứa các thẻ đánh số thứ tự khác nhau từ 0 đến 10.", "cauHoi": [{"question": "Chọn ngẫu nhiên 2 thẻ từ hộp 1. Số cách chọn là:", "choices": ["5050", "9900", "4590", "1000"], "correctIndex": 0, "explain": "Hộp 1 có $101$ thẻ (từ $0$ đến $100$).<br>Số cách chọn 2 thẻ khác nhau là:<br>\\[\n\t\tC_{101}^2 = \\dfrac{101 \\cdot 100}{2} = 5050\n\t\t\\]"}, {"question": "Chọn ngẫu nhiên từ mỗi hộp 1 thẻ. Xác suất để tổng 2 số thứ tự không vượt quá 90 là:", "choices": ["$\\dfrac{2}{9}$", "$\\dfrac{3}{11}$", "$\\dfrac{3}{7}$", "$\\dfrac{2}{11}$"], "correctIndex": 3, "explain": ""}, {"question": "Chọn ngẫu nhiên từ mỗi hộp 1 thẻ. Xác suất để tổng 2 số thứ tự không vượt quá 90 là:", "choices": ["$\\dfrac{82}{101}$", "$\\dfrac{59}{101}$", "$\\dfrac{25}{101}$", "$\\dfrac{86}{101}$"], "correctIndex": 3, "explain": "Hộp 1: số từ $0$ đến $100$ 101 số<br>Hộp 2: số từ $0$ đến $10$ 11 số<br>Tổng số cách chọn: $101 \\cdot 11 = 1111$<br>Để tổng không vượt quá 90: xét với mỗi số $y$ từ hộp 2 (từ 0 đến 10), số $x$ từ hộp 1 phải thỏa $x \\leq 90 - y$<br>Tính số cách thỏa mãn:<br>\\[\n\t\t\\sum_{y = 0}^{10} \\left( \\lfloor 90 - y \\rfloor + 1 \\right)\n\t\t= \\sum_{y = 0}^{10} (91 - y) = \\sum_{k = 81}^{91} k = 91 \\cdot 11 - \\sum_{y = 0}^{10} y\n\t\t= 91 \\cdot 11 - \\dfrac{10 \\cdot 11}{2} = 1001 - 55 = 946\n\t\t\\]<br>Xác suất: $\\dfrac{946}{1111} = \\dfrac{86}{101}$<br>Đáp án đúng là $\\boxed{\\dfrac{86}{101}}$"}]}, {"noiDungChung": "Cho tam giác $ABC$ có phương trình $(AB): 2x - y = 3$, điểm $B(1, -1)$, $C(6, 4)$.", "cauHoi": [{"question": "Gọi $I(x_0, y_0)$ là giao điểm của $BC$ với trục $Oy$. Tính $x_0 + y_0$.", "choices": ["2", "0", "4", "$-2$"], "correctIndex": 3, "explain": "Ta cần tìm giao điểm của đường thẳng $BC$ với trục $Oy$, tức là điểm có hoành độ $x = 0$ nằm trên đường thẳng $BC$.<br>Tìm phương trình đường thẳng $BC$ đi qua $B(1, -1)$ và $C(6, 4)$:<br>Hệ số góc:<br>\\[\n\t\tk = \\dfrac{4 - (-1)}{6 - 1} = \\dfrac{5}{5} = 1\n\t\t\\Rightarrow \\text{Phương trình: } y - (-1) = 1(x - 1) \\Rightarrow y = x - 2\n\t\t\\]<br>Thay $x = 0$ vào: $y = 0 - 2 = -2$<br>Giao điểm $I(0, -2)$ $x_0 + y_0 = 0 + (-2) = -2$"}, {"question": "Biết tam giác $ABC$ vuông tại $A$. Tìm hoành độ điểm $A$.", "choices": ["0", "4", "6", "2"], "correctIndex": 1, "explain": "Tam giác $ABC$ vuông tại $A$ hai vectơ $\\vec{AB}$ và $\\vec{AC}$ vuông góc.<br>Gọi $A(x, y)$ là điểm nằm trên đường thẳng $AB$: $2x - y = 3$<br>$y = 2x - 3$<br>Tính $\\vec{AB} = B - A = (1 - x, -1 - y)$<br>Tính $\\vec{AC} = C - A = (6 - x, 4 - y)$<br>Điều kiện vuông góc: $\\vec{AB} \\cdot \\vec{AC} = 0$  \\[\n\t\t(1 - x)(6 - x) + (-1 - y)(4 - y) = 0\n\t\t\\]  Thay $y = 2x - 3$ vào:  \\[\n\t\t(1 - x)(6 - x) + (-1 - (2x - 3))(4 - (2x - 3)) = 0\n\t\t\\Rightarrow (1 - x)(6 - x) + (-2x + 2)(-2x + 7) = 0\n\t\t\\]<br>Tính:  \\[\n\t\t(1 - x)(6 - x) = 6 - x - 6x + x^2 = x^2 - 7x + 6\n\t\t\\]  \\[\n\t\t(-2x + 2)(-2x + 7) = 4x^2 - 14x - 4x + 14 = 4x^2 - 12x + 14\n\t\t\\]  Tổng:<br>$\n\t\tx^2 - 7x + 6 + 4x^2 - 12x + 14 = 5x^2 - 19x + 20 = 0\n\t\t\\Rightarrow x = 2 \\text{ hoặc } x = 2\n\t\t x = 2$"}, {"question": "Biết có 2 đường tròn đi qua điểm $C(6, 4)$ và tiếp xúc đồng thời với trục $Ox$ và $Oy$. Tổng bán kính của hai đường tròn này là:", "choices": ["20", "$8\\sqrt{3}$", "16", "$12\\sqrt{2}$"], "correctIndex": 0, "explain": "Gọi tâm đường tròn là $I(a, a)$ vì tiếp xúc với cả $Ox$ và $Oy$ tâm nằm trên đường phân giác góc phần tư thứ nhất hoặc thứ ba.<br>Bán kính $R = a$<br>Đường tròn đi qua điểm $C(6, 4)$ khoảng cách từ $I(a, a)$ đến $C$ bằng $R$:<br>\\[\n\t\tIC = \\sqrt{(6 - a)^2 + (4 - a)^2} = a\n\t\t\\Rightarrow (6 - a)^2 + (4 - a)^2 = a^2\n\t\t\\Rightarrow 36 - 12a + a^2 + 16 - 8a + a^2 = a^2\n\t\t\\Rightarrow 52 - 20a + 2a^2 = a^2\n\t\t\\Rightarrow a^2 - 20a + 52 = 0\n\t\t\\]<br>Giải phương trình:<br>\\[\n\t\ta = \\dfrac{20 \\pm \\sqrt{400 - 208}}{2} = \\dfrac{20 \\pm \\sqrt{192}}{2} = \\dfrac{20 \\pm 8\\sqrt{3}}{2} = 10 \\pm 4\\sqrt{3}\n\t\t\\]<br>Tổng bán kính: $10 + 4\\sqrt{3} + 10 - 4\\sqrt{3} = 20$<br>Đáp án đúng là $\\boxed{20}$"}]}, {"noiDungChung": "Cho tứ diện $OABC$ có $\\vec{OA}, \\vec{OB}, \\vec{OC}$ đôi một vuông góc, $OA = \\dfrac{\\sqrt{2}}{2}$, $OB = OC = 1$.", "cauHoi": [{"question": "Chu vi tam giác $ABC$ là:", "choices": ["$\\sqrt{2}+\\sqrt{3}+\\sqrt{6}$", "$\\sqrt{3}+\\sqrt{6}$", "$\\sqrt{2}+\\sqrt{3}$", "$\\sqrt{2}+\\sqrt{6}$"], "correctIndex": 3, "explain": "Gọi $O$ là gốc tọa độ, ta có thể chọn:<br>\\[\n\t\tA = \\left(\\dfrac{\\sqrt{2}}{2}, 0, 0\\right),\\quad\n\t\tB = (0, 1, 0),\\quad\n\t\tC = (0, 0, 1)\n\t\t\\]<br>Tính độ dài các cạnh tam giác $ABC$:<br>\\[\n\t\tAB = \\sqrt{\\left(\\dfrac{\\sqrt{2}}{2}\\right)^2 + 1^2} = \\sqrt{\\dfrac{2}{4} + 1} = \\sqrt{\\dfrac{6}{4}} = \\dfrac{\\sqrt{6}}{2}\n\t\t\\]  \\[\n\t\tAC = \\sqrt{\\left(\\dfrac{\\sqrt{2}}{2}\\right)^2 + 1^2} = \\dfrac{\\sqrt{6}}{2}\n\t\t\\]<br>\\[\n\t\tBC = \\sqrt{(1)^2 + (1)^2} = \\sqrt{2}\n\t\t\\]<br>Chu vi tam giác $ABC$:<br>\\[\n\t\tP = AB + AC + BC = \\dfrac{\\sqrt{6}}{2} + \\dfrac{\\sqrt{6}}{2} + \\sqrt{2} = \\sqrt{6} + \\sqrt{2}\n\t\t\\]<br>Tuy nhiên, nếu tính lại chính xác:<br>\\[\n\t\tAB = \\sqrt{\\left(\\dfrac{\\sqrt{2}}{2}\\right)^2 + 1^2} = \\sqrt{\\dfrac{2}{4} + 1} = \\sqrt{\\dfrac{6}{4}} = \\sqrt{\\dfrac{3}{2}} = \\dfrac{\\sqrt{6}}{2}\n\t\t\\]<br>\\[\n\t\tAC = \\sqrt{\\left(\\dfrac{\\sqrt{2}}{2}\\right)^2 + 1^2} = \\dfrac{\\sqrt{6}}{2},\\quad BC = \\sqrt{(1)^2 + (1)^2} = \\sqrt{2}\n\t\t\\]<br>Chu vi: $\\dfrac{\\sqrt{6}}{2} + \\dfrac{\\sqrt{6}}{2} + \\sqrt{2} = \\sqrt{6} + \\sqrt{2}$<br>Đáp án đúng là $\\boxed{\\sqrt{2}+\\sqrt{6}}$"}, {"question": "Góc hợp bởi hai mặt phẳng $(ABC)$ và $(OBC)$ là:", "choices": ["$45^\\circ$", "$75^\\circ$", "$60^\\circ$", "$30^\\circ$"], "correctIndex": 0, "explain": "Góc giữa hai mặt phẳng $(ABC)$ và $(OBC)$ là góc giữa hai pháp tuyến của mặt phẳng.<br>- Mặt phẳng $(ABC)$ có pháp tuyến là $\\vec{n}_1 = \\vec{AB} \\times \\vec{AC}$  - Mặt phẳng $(OBC)$ có pháp tuyến là $\\vec{n}_2 = \\vec{OB} \\times \\vec{OC}$<br>Tính tích vô hướng:<br>\\[\n\t\t\\cos \\theta = \\dfrac{|\\vec{n}_1 \\cdot \\vec{n}_2|}{\\|\\vec{n}_1\\| \\cdot \\|\\vec{n}_2\\|}\n\t\t\\Rightarrow \\theta = \\arccos\\left(\\dfrac{1}{2}\\right) = 60^\\circ\n\t\t\\]<br>Đáp án đúng là $\\boxed{60^\\circ}$"}, {"question": "Gọi $H$ là hình chiếu vuông góc của $O$ lên mặt phẳng $(ABC)$. Tính thể tích khối tứ diện $OABH$.", "choices": ["$\\dfrac{\\sqrt{2}}{48}$", "$\\dfrac{\\sqrt{2}}{16}$", "$\\dfrac{\\sqrt{2}}{24}$", "$\\dfrac{\\sqrt{2}}{36}$"], "correctIndex": 0, "explain": "Thể tích tứ diện $OABH$:<br>\\[\n\t\tV = \\dfrac{1}{3} \\cdot S_{\\triangle ABH} \\cdot OH\n\t\t\\]<br>Vì $O$ vuông góc với mặt phẳng $(ABC)$, $OH$ là chiều cao từ $O$ xuống mặt phẳng $(ABC)$.<br>Ta có:  - $OA = \\dfrac{\\sqrt{2}}{2}$, $OB = 1$  - Góc giữa $\\vec{OA}$ và $\\vec{OB}$ là $90^\\circ$ tam giác $OAB$ vuông tại $O$<br>Diện tích tam giác $ABH$ bằng diện tích tam giác $ABO$:<br>\\[\n\t\tS = \\dfrac{1}{2} \\cdot OA \\cdot OB = \\dfrac{1}{2} \\cdot \\dfrac{\\sqrt{2}}{2} \\cdot 1 = \\dfrac{\\sqrt{2}}{4}\n\t\t\\]<br>Chiều cao $OH$ là khoảng cách từ $O$ đến mặt phẳng $(ABC)$, đã tính được là $\\dfrac{1}{2}$<br>Thể tích:<br>\\[\n\t\tV = \\dfrac{1}{3} \\cdot \\dfrac{\\sqrt{2}}{4} \\cdot \\dfrac{1}{2} = \\dfrac{\\sqrt{2}}{24}\n\t\t\\]<br>Đáp án đúng là $\\boxed{\\dfrac{\\sqrt{2}}{24}}$"}]}, {"noiDungChung": "Một công ty có 3 tuyến xe $1,2,3$ và in 3 bộ vé tháng 1, 3 bộ vé tháng 2. Mỗi tuyến sử dụng 1 bộ cho 1 tháng. Vé in theo quy tắc sau:<br>- Mỗi bộ 1 màu: xanh, đỏ, tím, vàng.  <br>- Ở mỗi tuyến, vé tháng 1 khác màu vé tháng 2.  <br>- Ở tuyến 3, vé tháng 1 hoặc vé tháng 2 có màu xanh.  <br>- Ở mỗi tháng, vé cho các tuyến khác nhau thì có màu khác nhau.  <br>- Một bộ vé ở tháng 1 có màu đỏ.  <br>- Vé tháng 1 của tuyến 2 màu tím.  <br>- Các vé tháng 2 không có màu tím.", "cauHoi": [{"question": "Nếu vé tháng 1 của tuyến 3 có màu đỏ thì điều nào phải đúng?", "choices": ["Vé tuyến 3 của tháng 2 có màu xanh", "Vé tuyến 1 của tháng 1 có màu vàng", "Vé tuyến 1 của tháng 1 có màu xanh", "Vé tuyến 2 của tháng 2 có màu vàng"], "correctIndex": 0, "explain": "Vé tháng 1 của tuyến 3 là đỏ tuyến 3 không thể dùng đỏ ở tháng 2 để thỏa điều kiện \"tuyến 3 có màu xanh ở tháng 1 hoặc tháng 2\", thì tháng 2 phải là xanh."}, {"question": "Nếu một bộ vé của tuyến 2 có màu xanh thì điều nào phải đúng?", "choices": ["Vé tuyến 3 của tháng 2 có màu xanh", "Vé tuyến 1 của tháng 1 có màu đỏ", "Vé tuyến 1 của tháng 2 có màu đỏ", "Vé tuyến 3 của tháng 1 có màu đỏ"], "correctIndex": 1, "explain": "Vé tháng 1 của tuyến 2 là tím màu xanh phải thuộc tháng 2. Vì vé tháng 2 của tuyến 2 là xanh, tuyến 3 không thể dùng xanh ở tháng 2 phải dùng xanh ở tháng 1. Khi đó, tuyến 1 có thể dùng đỏ ở tháng 1 để thỏa điều kiện \"một bộ vé tháng 1 có màu đỏ\"."}, {"question": "Phát biểu nào có thể đúng?", "choices": ["Vé tháng 2 không có màu xanh", "Chỉ có vé tuyến 2 màu đỏ", "Tháng 1 có 1 bộ vé xanh, 1 bộ vé vàng", "Vé tháng 1 không có màu xanh"], "correctIndex": 3, "explain": "Không có quy tắc nào cấm màu xanh ở tháng 1. Vì vậy, việc tháng 1 có 1 vé xanh, 1 vé vàng là hoàn toàn có thể xảy ra."}]}, {"noiDungChung": "Một dãy khách sạn đánh số từ 1 đến 7 từ trái sang phải. Một đoàn khách gồm $R, S, T, U, V, W, X$ được sắp xếp vào 7 phòng (mỗi người một phòng).<br>- Phòng của $T$ nằm bên trái phòng $R$.  <br>- Nếu $S$ ở phòng 4 thì $U$ ở phòng 5.  <br>- Nếu $U$ ở phòng 6 thì $S$ ở phòng 7.  <br>- $V$ và $W$ không ở cạnh phòng nhau.", "cauHoi": [{"question": "Liệt kê nào không thể là thứ tự phòng?", "choices": ["TRSUVXW", "XSUVTRW", "TXSUVRW", "VUTSXRW"], "correctIndex": 3, "explain": "Trong chuỗi XSUVTRW, ta thấy $V$ và $W$ ở vị trí 6 và 7 cạnh nhau vi phạm điều kiện."}, {"question": "Nếu $V$ và $W$ ở phòng 5 và 7 thì 2 người nào không thể ở phòng 6?", "choices": ["ST", "RS", "XR", "TU"], "correctIndex": 3, "explain": "Phòng 6 nằm giữa phòng 5 và 7 người ở phòng 6 sẽ cạnh cả $V$ và $W$. Vì $V$ và $W$ không được cạnh nhau, nên $T$ hoặc $U$ không thể ở giữa."}, {"question": "Biết $T$ ở phòng 3, $S$ ở phòng 4 thì phát biểu nào luôn đúng?", "choices": ["$R$ ở trái $V$", "$X$ ở 1 hoặc 2", "$X, T$ cạnh nhau", "$W$ trái $T$"], "correctIndex": 1, "explain": "$T$ ở phòng 3, $S$ ở phòng 4 $X$ có thể ở phòng 2 hoặc 4 mà phòng 4 là $S$ $X$ ở phòng 2 cạnh $T$."}]}, {"noiDungChung": ".<br>Cho bảng điểm của 5 lớp. Nếu điểm thấp hơn 5 sẽ rớt môn, từ 5 điểm trở lên sẽ qua môn.<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Lớp</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><5</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">5-8</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">>8</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">1</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">28</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">72</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">24</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">15</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">68</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">36</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">18</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">52</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">28</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">29</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">58</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">47</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">5</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">30</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">60</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">35</td></tr></table>", "cauHoi": [{"question": "Tổng số sinh viên của 5 lớp có bao nhiêu phần trăm rớt môn?", "choices": ["$18,8 \\%$", "$20 \\%$", "$15,6 \\%$", "$21,2 \\%$"], "correctIndex": 1, "explain": ""}, {"question": "Trong số các sinh viên trên 8 điểm có 20 (\\% sinh viên đạt điểm 10. Tỉ lệ sinh viên đạt điểm 10 của 5 lớp là:", "choices": ["$7,9 \\%$", "$7,16 \\%$", "$5,67 \\%$", "$20 \\%$"], "correctIndex": 2, "explain": ""}, {"question": "Trong lớp mà tỉ lệ sinh viên rớt môn nhiều nhất, 1 số bạn đã phúc khảo và qua môn nên lớp đó không còn là lớp có tỉ lệ rớt môn nhiều nhất. Có ít nhất bao nhiêu bạn tăng điểm và qua môn sau khi phúc khảo?", "choices": ["4", "1", "2", "3"], "correctIndex": 2, "explain": ""}]}, {"noiDungChung": ".<br>Số vở bán ra (đơn vị: nghìn cuốn) trong năm 2023 và 2024 của 6 công ty $1,2,3,4,5,6$ được thống kê như sau:<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Công ty</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Năm 2023</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Năm 2024</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">1</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">80</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">105</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">75</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">65</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">95</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">110</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">85</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">95</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">5</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">75</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">95</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">6</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">70</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">80</td></tr></table>", "cauHoi": [{"question": "Tổng số vở (nghìn cuốn) trong 2 năm của các công ty $1,3,5$ là:", "choices": ["250", "560", "310", "435"], "correctIndex": 1, "explain": ""}, {"question": "Tỉ lệ tổng số vở bán trong 2 năm của công ty 2 so với công ty 4 là:", "choices": ["$3: 5$", "$7: 9$", "$4: 5$", "$2: 3$"], "correctIndex": 1, "explain": ""}, {"question": "Trong năm 2023, giá bán vở của công ty 5 và 6 như nhau. Trong năm 2024, công ty 5 tăng 10\\%, công ty 6 tăng 15 (\\% so với giá năm 2023. Tỉ lệ doanh thu công ty 5 với công ty 6 trong cả 2 năm là:", "choices": ["$113,5 \\%$", "$88 \\%$", "$110,8 \\%$", "$90,3 \\%$"], "correctIndex": 2, "explain": ""}]}]}, {"id": "de-1-2026", "ten": "Đề chính thức đợt 1 - 5/4/2026", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Một công ty có lợi nhuận tuân theo hàm số $y=f(x)=\\sqrt{x^2-x+5}-\\sqrt{x^2+2x+2}$. Trong đó, $f(x)$ là lợi nhuận (đơn vị: tỷ đồng), $x$ là thời gian (đơn vị: năm). Sau rất lâu (có thể coi $x$ tiến tới $+\\infty$), nhận xét đúng về lợi nhuận của công ty đó là", "choices": ["Công ty lỗ", "Không xác định", "Công ty lời", "Công ty hòa vốn"], "correctIndex": 0, "explain": "Ta có   $$\\displaystyle\\lim\\limits_{x\\to+\\infty}y=\\displaystyle\\lim\\limits_{x\\to+\\infty}\\dfrac{(x^2-x+5)-(x^2+2x+2)}{\\sqrt{x^2-x+5}+\\sqrt{x^2+2x+2}}=\\displaystyle\\lim\\limits_{x\\to+\\infty}\\dfrac{-3x+3}{\\sqrt{x^2-x+5}+\\sqrt{x^2+2x+2}}=\\dfrac{-3}{1+1}=-\\dfrac{3}{2}$$  Do đó: công ty đang bị lỗ."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Nếu $\\displaystyle\\int\\limits_{{1}}^{{3}}({(m+1)}x^{m}+{1})\\mathrm{d}x={28}$ thì", "choices": ["Không tồn tại giá trị của $m$", "$m\\in{[{1};{3}]}$", "$m\\in{[-{3};-{1})}$", "$m\\in{(-{1};{1})}$"], "correctIndex": 1, "explain": "Ta có $\\displaystyle\\int\\limits_{{1}}^{{3}}({(m+1)}x^{m}+{1})\\mathrm{d}x={[{x}^{m+1}+x]}_{{1}}^{{3}}={({3}^{m+1}+{3})}-({{1}}^{m+1}+{1})={3}^{m+1}+{1}$.<br>Thay vào phương trình ta được:  $${3}^{m+1}+{1}={28}\\Leftrightarrow{3}^{m+1}={27}\\Leftrightarrow{3}^{m+1}={3}^{3}\\Leftrightarrow m+{1}={3}\\Leftrightarrow m={2}$$  Giá trị $m={2}$ nằm trong đoạn ${[{1};{3}]}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trong mặt phẳng $Oxy$, một khu vườn được giới hạn bởi đồ thị của hai hàm số $y=\\dfrac{{1}}{{2}}x^{2}$ và $y=\\sqrt{{2}x}$. Diện tích khu vườn là", "choices": ["$\\dfrac{{5}}{{3}}$", "${2}$", "${1}$", "$\\dfrac{{4}}{{3}}$"], "correctIndex": 3, "explain": "Phương trình hoành độ giao điểm của hai đồ thị (điều kiện $x\\ge{0}$):  $$\\dfrac{{1}}{{2}}x^{2}=\\sqrt{{2}x}\\Leftrightarrow\\dfrac{{1}}{{4}}x^{4}={2}x\\Leftrightarrow x^{4}-{8}x={0}\\Leftrightarrow x(x^{3}-{8})={0}\\Leftrightarrow\\hoac{&x={0}<br>&x={2}}$$  Diện tích khu vườn là  $$S=\\displaystyle\\int\\limits_{{0}}^{{2}}\\left|\\sqrt{{2}x}-\\dfrac{{1}}{{2}}x^{2}\\right|\\mathrm{d}x=\\left.\\left(\\dfrac{{2}\\sqrt{{2}}}{{3}}x\\sqrt{x}-\\dfrac{{1}}{{6}}x^{3}\\right)\\right|_{{0}}^{{2}}=\\dfrac{{4}}{{3}}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một phân tử được cấu tạo từ ${8}$ nguyên tử liên kết với nhau. Tổng số liên kết trong phân tử này là ${8}$. Các nhà khoa học đo được số liên kết của ${7}$ nguyên tử đầu tiên là ${4}$, ${2}$, ${2}$, ${1}$, ${1}$, ${1}$, ${1}$. Nguyên tử thứ ${8}$ có bao nhiêu liên kết?", "choices": ["${1}$", "${4}$", "${2}$", "${3}$"], "correctIndex": 1, "explain": "Gọi $x$ là số bậc (số liên kết) của nguyên tử thứ ${8}$. Ta thiết lập phương trình:  $${4}+{2}+{2}+{1}+{1}+{1}+{1}+x={2}\\times{8}\\Leftrightarrow{12}+x={16}\\Leftrightarrow x={4}$$  \\begin{center}  \\begin{tikzpicture}[scale=0.9]<br>\\foreach \\i/\\name/\\label in {1/1/4, 2/2/2, 3/3/2, 4/4/1, 5/5/1, 6/6/1, 7/7/1, 8/8/$x=4$} {  \\node (\\i) at ({360/8 * (\\i - 1)}:2.5cm) {\\name};  }<br>\\draw (1) -- (2);  \\draw (1) -- (3);  \\draw (1) -- (4);  \\draw (1) -- (5);<br>\\draw (2) -- (6);  \\draw (2) -- (7);<br>\\draw (3) -- (8);  \\draw (3) -- (5);<br>\\node[draw=none, font=\\normalsize] at (0,-3.3) {Đồ thị minh họa số liên kết của 8 nguyên tử};  \\end{tikzpicture}  \\end{center}"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một khu du lịch gồm $6$ địa điểm $A$, $B$, $C$, $D$, $E$, $F$ được nối với nhau. Bạn Thủy muốn đi từ $E$ lần lượt qua các điểm khác và kết thúc tại $F$.  \\begin{center}<br>\\end{center}  Số cách đi là<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1]\n\t\t\t\\coordinate (A) at (0,3);\n\t\t\t\\coordinate (B) at (3,3);\n\t\t\t\\coordinate (C) at (3,0);\n\t\t\t\\coordinate (D) at (0,0);\n\t\t\t\\coordinate (E) at (1.5,2.2);\n\t\t\t\\coordinate (F) at (1.5,0.8);\n\t\t\t\\draw (A)--(B)--(C)--(D)--(A);\n\t\t\t\\draw (A)--(E) (B)--(E) (E)--(F);\n\t\t\t\\draw (F)--(C) (F)--(D);\n\t\t\t\\foreach \\p/\\l in {A/above left, B/above right, C/below right, D/below left, E/above, F/below}\n\t\t\t\\node[\\l] at (\\p){$\\p$};\n\t\t\\end{tikzpicture}</script></div>", "choices": ["$3$", "$2$", "$1$", "$4$"], "correctIndex": 1, "explain": "<b>Đi theo nhánh $E\\to A$}:<br>Từ $A$, muốn đi qua hết các điểm còn lại để về $F$, lộ trình duy nhất không bị cụt đường là $A\\to B\\to C\\to D$.<br>Đến $D$, ta thấy $D$ có đường nối trực tiếp với $F$.<br>$\\Rightarrow$ Đường đi hợp lệ $1$: $E\\to A\\to B\\to C\\to D\\to F$.<br>(<i>Nhánh rẽ khác $A\\to D\\to C\\to B$ sẽ bị tắc vì $B$ không nối thẳng với $F$}).<br><b>Đi theo nhánh $E\\to B$}:<br>Tương tự, lộ trình quét qua các điểm còn lại là $B\\to A\\to D\\to C$.<br>Đến $C$, ta thấy $C$ có đường nối trực tiếp với $F$.<br>$\\Rightarrow$ Đường đi hợp lệ $2$: $E\\to B\\to A\\to D\\to C\\to F$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho một tam giác có độ dài ${3}$ cạnh ${5}$, ${6}$, ${7}$. Tính độ dài đường cao ứng với cạnh có độ dài bằng ${6}$.", "choices": ["$\\sqrt{{2}}$", "${2}\\sqrt{{2}}$", "${2}\\sqrt{{6}}$", "$\\sqrt{{6}}$"], "correctIndex": 2, "explain": "Nửa chu vi: $p=\\dfrac{{5}+{6}+{7}}{{2}}={9}$.<br>Diện tích (Heron): $S=\\sqrt{{9}({9}-{5})({9}-{6})({9}-{7})}={6}\\sqrt{{6}}$<br>Đường cao $h_{{6}}=\\dfrac{{2}S}{{6}}=\\dfrac{{12}\\sqrt{{6}}}{{6}}={2}\\sqrt{{6}}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $\\Delta ABC$ thỏa mãn $\\dfrac{\\tan B}{\\tan C}=\\dfrac{\\sin^{2}B}{\\sin^{2}C}$. Khi đó $\\Delta ABC$:", "choices": ["cân", "vuông", "đều", "vuông hoặc cân"], "correctIndex": 3, "explain": "$$\\dfrac{\\dfrac{\\sin B}{\\cos B}}{\\dfrac{\\sin C}{\\cos C}}=\\dfrac{\\sin^{2}B}{\\sin^{2}C}\\Leftrightarrow\\dfrac{\\sin B\\cos C}{\\cos B\\sin C}=\\dfrac{\\sin^{2}B}{\\sin^{2}C}\\Leftrightarrow\\sin C\\cos C=\\sin B\\cos B\\Leftrightarrow\\sin({2}C)=\\sin({2}B)$$  Trường hợp ${1}$: ${2}C={2}B\\Leftrightarrow B=C$ (Tam giác cân).<br>Trường hợp ${2}$: ${2}C={180}^{\\circ}-{2}B\\Leftrightarrow B+C={90}^{\\circ}$ (Tam giác vuông)."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Giá trị của $m$ để bất phương trình $\\log_{\\dfrac{1}{5}}m>\\log_{5}({2}x+{3})$ có đúng ${3}$ nghiệm nguyên.", "choices": ["$\\dfrac{{1}}{{7}}\\leq m<\\dfrac{{1}}{{5}}$", "${0}<m<{1}$", "$\\dfrac{{1}}{{7}}<m<\\dfrac{{1}}{{3}}$", "$\\dfrac{{1}}{{5}}<m<\\dfrac{{1}}{{3}}$"], "correctIndex": 0, "explain": "Điều kiện xác định của các biểu thức logarit là $m>{0}$ và ${2}x+{3}>{0}\\Leftrightarrow x>-\\dfrac{{3}}{{2}}=-{1}{,}5$.<br>$\\log_{\\dfrac{1}{5}}m>\\log_{5}({2}x+{3})\\Leftrightarrow-\\log_{5}m>\\log_{5}({2}x+{3})\\Leftrightarrow\\log_{5}\\left(\\dfrac{{1}}{m}\\right)>\\log_{5}({2}x+{3})$<br>$\\Rightarrow\\dfrac{{1}}{m}>{2}x+{3}\\Leftrightarrow{2}x<\\dfrac{{1}}{m}-{3}\\Leftrightarrow x<\\dfrac{{1}-{3}m}{{2}m}$<br>Để phương trình có đúng ${3}$ nghiệm nguyên: ${1}<\\dfrac{{1}-{3}m}{{2}m}\\le{2}$<br>Giải hệ bất phương trình này: $m\\in\\left[\\dfrac{{1}}{{7}};\\dfrac{{1}}{{5}}\\right)$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Gọi $S$ là tập nghiệm của bất phương trình $\\dfrac{x^{2}+x+{3}}{x^{2}-{4}}\\ge{1}$. Khi đó $S\\cap({-2};{2})$:", "choices": ["$(-{1};{2})$", "$(-{2};-{1})$", "$\\varnothing$", "$(-{2};{1})$"], "correctIndex": 2, "explain": "Điều kiện: $x\\neq\\pm{2}$.<br>Bất phương trình tương đương:  $$\\dfrac{x^{2}+x+{3}}{x^{2}-{4}}-{1}\\ge{0}\\Leftrightarrow\\dfrac{x^{2}+x+{3}-(x^{2}-{4})}{x^{2}-{4}}\\ge{0}\\Leftrightarrow\\dfrac{x+{7}}{x^{2}-{4}}\\ge{0}$$  Lập bảng xét dấu, ta có tập nghiệm $S={[-{7};-{2})}\\cup({2};+\\infty)$.<br>Khi đó, giao của $S$ với khoảng $(-{2};{2})$ là: $S\\cap(-{2};{2})=\\varnothing$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Xét ${2}$ số thực $x$, $y$ thỏa mãn $x,y>{0}$ $\\log_{x}(y^{5x})=\\log_{y}(x^{8y})={20}$. Tính $xy$.", "choices": ["${4}$", "${40}$", "${2}$", "${10}$"], "correctIndex": 3, "explain": "Điều kiện: $x,y>{0}$ và $x,y\\neq{1}$.<br>Ta có hệ phương trình:  $$\\heva{&\\log_{x}(y^{5x})={20}<br>&\\log_{y}(x^{8y})={20}}\\Leftrightarrow\\heva{&{5}x\\cdot\\log_{x}y={20}<br>&{8}y\\cdot\\log_{y}x={20}}\\Leftrightarrow\\heva{&\\log_{x}y=\\dfrac{{4}}{x}<br>&\\log_{y}x=\\dfrac{{5}}{{2}y}}$$  Nhân vế theo vế: $\\dfrac{{4}}{x}\\cdot\\dfrac{{5}}{{2}y}={1}\\Leftrightarrow\\dfrac{{20}}{{2}xy}={1}\\Leftrightarrow{2}xy={20}\\Leftrightarrow xy={10}$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tập nghiệm của bất phương trình $|{2}x-{3}|>x+{1}$ là", "choices": ["$\\mathbb{R}$", "$\\left(-\\infty;-\\dfrac{{4}}{{3}}\\right)$", "$({2};+\\infty)$", "$\\left(-\\infty;\\dfrac{{2}}{{3}}\\right)\\cup({4};+\\infty)$"], "correctIndex": 3, "explain": "$$|{2}x-{3}|>x+{1}\\Leftrightarrow\\hoac{&{2}x-{3}>x+{1}<br>&{2}x-{3}<-(x+{1})}\\Leftrightarrow\\hoac{&x>{4}<br>&{2}x-{3}<-x-{1}}\\Leftrightarrow\\hoac{&x>{4}<br>&{3}x<{2}}\\Leftrightarrow\\hoac{&x>{4}<br>&x<\\dfrac{{2}}{{3}}}$$  Tập nghiệm của bất phương trình là $\\left(-\\infty;\\dfrac{{2}}{{3}}\\right)\\cup({4};+\\infty)$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết đồ thị hàm số $y=\\dfrac{{6}-{4}x}{{2}x+{3}}$ có ${2}$ tiệm cận giao với $Ox$, $Oy$ tạo thành hình chữ nhật. Diện tích của hình chữ nhật:", "choices": ["${3}$", "${4}$", "${6}$", "${12}$"], "correctIndex": 0, "explain": "Tiệm cận đứng: ${2}x+{3}={0}\\Leftrightarrow x=-\\dfrac{{3}}{{2}}$. Khoảng cách từ trục $Oy$ đến tiệm cận đứng là $a=\\left|-\\dfrac{{3}}{{2}}\\right|=\\dfrac{{3}}{{2}}$.<br>Tiệm cận ngang: $y=\\dfrac{-{4}}{{2}}=-{2}$. Khoảng cách từ trục $Ox$ đến tiệm cận ngang là $b=|-{2}|={2}$.<br>Diện tích hình chữ nhật tạo bởi hai tiệm cận và hai trục tọa độ là: $S=a\\cdot b=\\dfrac{{3}}{{2}}\\cdot{2}={3}$"}]}, {"noiDungChung": "Một nhà máy sử dụng ${2}$ nguyên liệu $X$ và $Y$ để sản xuất sản phẩm mỹ nghệ. Tổng khối lượng nguyên liệu không quá ${8}$ tạ. Biết rằng để sản xuất ${1}$ tạ nguyên liệu $X$ mất ${20}$ ngày và thu được ${3}$ tỷ đồng; để sản xuất ${1}$ tạ nguyên liệu $Y$ thì mất ${30}$ ngày và thu được ${4}$ tỷ đồng. Tổng số ngày làm việc không quá ${180}$ ngày. Gọi $x$ và $y$ lần lượt là khối lượng (tính bằng tạ) của nguyên liệu $X$ và nguyên liệu $Y$ mà nhà máy sử dụng ($x\\ge{0}$, $y\\ge{0}$).", "cauHoi": [{"question": "Bất phương trình biểu diễn số ngày làm việc:", "choices": ["${2}x+{3}y\\le{18}$", "$x+y\\le{8}$", "${2}x+{3}y\\ge{18}$", "$x+y\\ge{8}$"], "correctIndex": 0, "explain": "Theo giả thiết, ${1}$ tạ nguyên liệu $X$ cần ${20}$ ngày, vậy $x$ tạ cần ${20}x$ ngày.<br>Tương tự, ${1}$ tạ nguyên liệu $Y$ cần ${30}$ ngày, vậy $y$ tạ cần ${30}y$ ngày.<br>Tổng số ngày làm việc không quá ${180}$ ngày, ta có bất phương trình: ${20}x+{30}y\\le{180}$<br>Chia cả hai vế cho ${10}$, ta được bất phương trình rút gọn: ${2}x+{3}y\\le{18}$"}, {"question": "Lợi nhuận lớn nhất là:", "choices": ["${30}$", "${24}$", "${28}$", "${26}$"], "correctIndex": 3, "explain": "Ta cần tìm giá trị lớn nhất của hàm lợi nhuận $F(x,y)={3}x+{4}y$ (tỷ đồng) dựa trên hệ bất phương trình ràng buộc sau:  $$\\heva{&x\\ge{0}<br>&y\\ge{0}<br>&x+y\\le{8}<br>&{2}x+{3}y\\le{18}}$$<br>\\begin{center}  \\begin{tikzpicture}[scale=0.8]<br>\\draw[step=1cm, gray!30, dashed] (-1,-1) grid (9,9);  \\draw[->, thick] (-1,0) -- (9.5,0) node[right] {$x$};  \\draw[->, thick] (0,-1) -- (0,9.5) node[above] {$y$};<br>\\foreach \\x in {2,4,6,8}  \\draw (\\x, 0.1) -- (\\x, -0.1) node[below, font=\\footnotesize] {\\x};  \\foreach \\y in {2,4,6,8}  \\draw (0.1, \\y) -- (-0.1, \\y) node[left, font=\\footnotesize] {\\y};  \\node[below left, font=\\footnotesize] at (0,0) {$0$};<br>\\fill[gray, opacity=0.3] (0,0) -- (0,6) -- (6,2) -- (8,0) -- cycle;<br>\\draw[blue, thick] (0,8) -- (8,0) node[midway, above right, sloped, font=\\footnotesize] {$x+y=8$};<br>\\draw[red, thick] (0,6) -- (9,0) node[midway, below left, sloped, font=\\footnotesize] {$2x+3y=18$};<br>\\filldraw (0,0) circle (2pt) node[above left, font=\\footnotesize] {$A$};  \\filldraw (0,6) circle (2pt) node[above right, font=\\footnotesize] {$B$};  \\filldraw (8,0) circle (2pt) node[below right, font=\\footnotesize] {$C$};  \\filldraw (6,2) circle (2pt) node[above right, font=\\footnotesize] {$D$};<br>\\node[fill=yellow!20, draw=orange, rounded corners, font=\\small\\bfseries] at (6.8, 5) {$F_{max} = 26$ tại $D(6;2)$};  \\draw[->, orange, thick] (6.5, 4.5) -- (6.1, 2.1);<br>\\end{tikzpicture}  \\end{center}  Ta đi tìm các đỉnh của đa giác miền nghiệm bằng cách giải các hệ phương trình giao điểm:<br>- Giao của $x={0}$ và $y={0}\\Rightarrow A({0};{0})$  <br>- Giao của $x={0}$ và ${2}x+{3}y={18}\\Rightarrow B({0};{6})$  <br>- Giao của $y={0}$ và $x+y={8}\\Rightarrow C({8};{0})$  <br>- Giao của $x+y={8}$ và ${2}x+{3}y={18}$: $\\Rightarrow D({6};{2})$<br>Thay tọa độ các đỉnh vào hàm mục tiêu $F(x,y)={3}x+{4}y$:<br>- Tại $A({0};{0})$: $F={3}({0})+{4}({0})={0}$  <br>- Tại $B({0};{6})$: $F={3}({0})+{4}({6})={24}$  <br>- Tại $C({8};{0})$: $F={3}({8})+{4}({0})={24}$  <br>- Tại $D({6};{2})$: $F={3}({6})+{4}({2})={18}+{8}={26}$<br>So sánh các giá trị, ta thấy lợi nhuận lớn nhất đạt được là ${26}$ tỷ đồng khi sử dụng ${6}$ tạ nguyên liệu $X$ và ${2}$ tạ nguyên liệu $Y$."}]}, {"noiDungChung": "Bạn $A$ thả quả bóng cao su từ độ cao ${10}\\text{ m}$ theo phương thẳng đứng. Mỗi khi chạm đất nó lại nảy lên theo phương thẳng đứng một đoạn bằng $\\dfrac{{3}}{{4}}$ độ cao trước đó.", "cauHoi": [{"question": "Sau ${5}$ lần chạm đất độ cao cực đại của quả bóng là", "choices": ["${3}{,}{16}$", "${1}{,}{78}$", "${2}{,}{37}$", "${3}{,}{25}$"], "correctIndex": 2, "explain": "Gọi $h_{{0}}={10}$ là độ cao ban đầu của quả bóng (đơn vị: mét).<br>Độ cao cực đại của quả bóng sau lần chạm đất thứ $n$ lập thành một cấp số nhân với công bội $q=\\dfrac{{3}}{{4}}$.<br>Sau lần chạm đất thứ ${5}$, độ cao cực đại của quả bóng là:  $$h_{{5}}=h_{{0}}\\cdot q^{{5}}={10}\\cdot\\left(\\dfrac{{3}}{{4}}\\right)^{{5}}={10}\\cdot\\dfrac{{243}}{{1024}}=\\dfrac{{1215}}{{512}}\\approx{2}{,}{37}\\text{ (m)}$$"}, {"question": "Tổng quãng đường quả bóng đi được đến khi dừng hẳn:", "choices": ["${40}$", "${70}$", "${50}$", "${80}$"], "correctIndex": 1, "explain": "Quãng đường quả bóng đi được bao gồm:<br>- Quãng đường rơi xuống lần đầu tiên: $S_{{0}}=h_{{0}}={10}$.  <br>- Quãng đường nảy lên và rơi xuống sau các lần chạm đất tiếp theo (mỗi lần gồm một lượt lên và một lượt xuống bằng nhau).<br>- Lần này ${1}$: lên $h_{{1}}$, xuống $h_{{1}}\\Rightarrow$ quãng đường ${2}h_{{1}}$  <br>- Lần này ${2}$: lên $h_{{2}}$, xuống $h_{{2}}\\Rightarrow$ quãng đường ${2}h_{{2}}$  <br>- $\\dots$<br>Tổng quãng đường quả bóng đi được cho đến khi dừng hẳn là tổng của một cấp số nhân lùi vô hạn:  $$S=h_{{0}}+{2}h_{{1}}+{2}h_{{2}}+{2}h_{{3}}+\\dots$$  $$S=h_{{0}}+{2}(h_{{1}}+h_{{2}}+h_{{3}}+\\dots)$$  Cụm trong ngoặc là tổng của cấp số nhân lùi vô hạn với số hạng đầu $u_{{1}}=h_{{1}}={10}\\cdot\\dfrac{{3}}{{4}}={7}{,}{5}$ và công bội $q=\\dfrac{{3}}{{4}}$.<br>Tổng cấp số nhân lùi vô hạn này là: $S=\\dfrac{u_{{1}}}{{1}-q}=\\dfrac{{7}{,}{5}}{{1}-\\dfrac{{3}}{{4}}}=\\dfrac{{7}{,}{5}}{{0}{,}{25}}={30}$.<br>Vậy tổng quãng đường quả bóng đi được là: $S={10}+{2}\\cdot{30}={10}+{60}={70}\\text{ (m)}$"}]}, {"noiDungChung": "Trong hệ trục tọa độ $Oxyz$, cho điểm $A({1};{1};{1})$; $B({2};{0};{2})$ và $C({3};{1};-{3})$.", "cauHoi": [{"question": "Tính độ dài đoạn thẳng $AB$", "choices": ["${2}$", "$\\sqrt{{3}}$", "${2}\\sqrt{{6}}$", "${2}\\sqrt{{3}}$"], "correctIndex": 1, "explain": "$\\vec{AB}=({2}-{1};{0}-{1};{2}-{1})=({1};-{1};{1})$<br>Độ dài đoạn thẳng $AB$ chính là độ dài của vectơ $\\vec{AB}$: $AB=|\\vec{AB}|=\\sqrt{{1}^{2}+(-{1})^{2}+{1}^{2}}=\\sqrt{{1}+{1}+{1}}=\\sqrt{{3}}$"}, {"question": "Trong hệ trục tọa độ $Oxyz$, cho điểm $A({1};{1};{1})$; $B({2};{0};{2})$ và $C({3};{1};-{3})$. Tìm giao điểm của $(ABC)$ và $Ox$", "choices": ["$E({3};{0};{0})$", "$E({2};{0};{0})$", "$E({1};{0};{0})$", "$E({0};{3};{0})$"], "correctIndex": 0, "explain": "$\\vec{AB}=({1};-{1};{1})$.<br>$\\vec{AC}=({2};{0};-{4})$<br>$\\vec{n}=[\\vec{AB},\\vec{AC}]=\\left(\\left|\\begin{matrix}-{1}&{1}\\\\{0}&-{4}\\end{matrix}\\right|;\\left|\\begin{matrix}{1}&{1}\\\\-{4}&{2}\\end{matrix}\\right|;\\left|\\begin{matrix}{1}&-{1}\\\\{2}&{0}\\end{matrix}\\right|\\right)=({4};{6};{2})$<br>Để phương trình gọn hơn, ta có thể chọn vecto pháp tuyến là $\\vec{n}'=\\dfrac{{1}}{{2}}\\vec{n}=({2};{3};{1})$.<br>Mặt phẳng $(ABC)$ đi qua điểm $A({1};{1};{1})$ và có vecto pháp tuyến $\\vec{n}'({2};{3};{1})$ có phương trình tổng quát là:<br>${2}(x-{1})+{3}(y-{1})+{1}(z-{1})={0}\\Leftrightarrow{2}x-{2}+{3}y-{3}+z-{1}={0}\\Leftrightarrow{2}x+{3}y+z-{6}={0}$<br>Gọi $M$ là giao điểm của mặt phẳng $(ABC)$ và trục $Ox$. Vì điểm $M$ nằm trên trục $Ox$ nên tọa độ của nó có dạng $M(x;{0};{0})$.<br>Vì $M\\in(ABC)$, ta thay tọa độ của điểm $M$ vào phương trình mặt phẳng $(ABC)$ vừa tìm được:<br>${2}x+{3}({0})+{0}-{6}={0}\\Leftrightarrow{2}x-{6}={0}\\Leftrightarrow x={3}$<br>Vậy tọa độ của điểm $M$ là $({3};{0};{0})$."}]}, {"noiDungChung": "Có ${6}$ ghế xếp thành hàng ngang. Xếp ngẫu nhiên ${6}$ học sinh vào hàng ghế này, trong đó có ${3}$ học sinh lớp $A$, ${2}$ học sinh lớp $B$ và ${1}$ học sinh lớp $C$.", "cauHoi": [{"question": "Số cách xếp ${6}$ học sinh ngồi vào hàng là", "choices": ["${6}!$", "${6}!-1$", "$C_{{6}}^{{4}}$", "$A_{{6}}^{{4}}$"], "correctIndex": 0, "explain": "Số cách xếp là $P_{{6}}={6}!$ (cách)."}, {"question": "Số cách xếp sao cho hai học sinh lớp $B$ ngồi hai đầu ghế là", "choices": ["${48}$", "${42}$", "${60}$", "${124}$"], "correctIndex": 0, "explain": "Xếp ${2}$ học sinh lớp $B$ vào ${2}$ vị trí đầu và cuối của hàng ghế, có: $P_{{2}}={2}!={2}$ (cách).<br>Xếp ngẫu nhiên ${4}$ học sinh còn lại vào ${4}$ ghế trống, số cách xếp là: $P_{{4}}={4}!={24}$ (cách).<br>Áp dụng quy tắc nhân, tổng số cách xếp thoả mãn yêu cầu bài toán là: ${2}!\\times{4}!={2}\\times{24}={48}$ (cách)."}, {"question": "Xác suất để xếp học sinh lớp $C$ chỉ ngồi cạnh học sinh lớp $B$ là", "choices": ["$\\dfrac{{1}}{{6}}$", "$\\dfrac{{2}}{{15}}$", "$\\dfrac{{1}}{{5}}$", "$\\dfrac{{3}}{{20}}$"], "correctIndex": 2, "explain": "Không gian mẫu: Xếp ngẫu nhiên ${6}$ học sinh vào ${6}$ ghế: $n(\\Omega)={6}!=720$.<br>Gọi $X$ là biến cố: \"Học sinh lớp $C$ chỉ ngồi cạnh học sinh lớp $B$\".<br>Chia làm ${2}$ trường hợp:<br>- Trường hợp ${1}$: Học sinh $C$ ngồi ở ${1}$ trong ${2}$ ghế ngoài cùng (ghế số ${1}$ hoặc ghế số ${6}$).  + Chọn vị trí cho học sinh $C$ (ghế đầu hoặc ghế cuối): Có ${2}$ cách.<br>+ Chọn ${1}$ học sinh lớp $B$ ngồi cạnh học sinh $C$: Có ${2}$ cách.<br>+ Xếp ${4}$ học sinh còn lại vào ${4}$ ghế trống: Có ${4}!=24$ cách.<br>+ Số cách xếp cho trường hợp ${1}$ là: ${2}\\times{2}\\times24={96}$ (cách).  <br>- Trường hợp ${2}$: Học sinh $C$ ngồi ở các ghế giữa (ghế số ${2}$, ${3}$, ${4}$, ${5}$).<br>Lúc này, học sinh $C$ có đúng ${2}$ người ngồi cạnh hai bên. Yêu cầu bài toán buộc cả ${2}$ người này đều phải là học sinh lớp $B$. Vì chỉ có đúng ${2}$ học sinh lớp $B$, nên ta sẽ tạo thành một cụm cố định gồm ${3}$ học sinh: (Học sinh $B$ - Học sinh $C$ - Học sinh $B$).<br>- Sắp xếp vị trí của ${2}$ học sinh lớp $B$ trong cụm này: Có ${2}!={2}$ cách.  <br>- Coi cụm ${3}$ học sinh này là một phần tử. Cùng với ${3}$ học sinh lớp $A$ còn lại, ta có tổng cộng ${4}$ phần tử cần xếp vào hàng ngang. Số cách hoán vị ${4}$ phần tử này là: ${4}!=24$ cách.  <br>- Số cách xếp cho trường hợp ${2}$ là: ${2}\\times24={48}$ (cách).<br>Tổng số kết quả thuận lợi cho biến cố $X$ là: $n(X)={96}+{48}=144$ (cách).<br>Xác suất của biến cố $X$ là: $P(X)=\\dfrac{n(X)}{n(\\Omega)}=\\dfrac{144}{720}=\\dfrac{{1}}{{5}}$"}]}, {"noiDungChung": "Cho tọa độ các điểm $A({1};{2})$, $B(-{1};{1})$, $C({3};-{1})$.", "cauHoi": [{"question": "Tọa độ trung điểm $M$ của $BC$ là", "choices": ["$M({1};{0})$", "$M({0};{1})$", "$M\\left({0};\\dfrac{{3}}{{2}}\\right)$", "$M\\left(-{1};\\dfrac{{3}}{{2}}\\right)$"], "correctIndex": 0, "explain": "Trung điểm $M$ của $BC$ có tọa độ:  $x_M = \\dfrac{x_B + x_C}{{2}} = \\dfrac{-{1}+{3}}{{2}} = {1}$; $y_M = \\dfrac{y_B + y_C}{{2}} = \\dfrac{{1}-{1}}{{2}} = {0}$. Vậy $M({1};{0})$."}, {"question": "Phương trình tổng quát đường cao kẻ từ đỉnh $A$ của tam giác $ABC$ là", "choices": ["${2}x-y={0}$", "${2}x+y={0}$", "${2}x-{3}y={0}$", "$x-{2}y={0}$"], "correctIndex": 0, "explain": "Đường cao kẻ từ $A$ đi qua $A({1};{2})$ và vuông góc với $BC$.<br>Véctơ $\\vec{BC} = ({4};-{2})$, chọn véctơ pháp tuyến $\\vec{n} = ({2};-{1})$.<br>Phương trình: ${2}(x-{1}) - {1}(y-{2}) = {0} \\Leftrightarrow {2}x - y = {0}$."}, {"question": "Tổng hoành độ và tung độ của tâm đường tròn ngoại tiếp tam giác $ABC$", "choices": ["$\\dfrac{{4}}{{7}}$", "$\\dfrac{{5}}{{8}}$", "$\\dfrac{{3}}{{5}}$", "$\\dfrac{{3}}{{8}}$"], "correctIndex": 1, "explain": "Gọi phương trình đường tròn loại 2 là $(C): x^2 + y^2 + ax + by + c = 0$.  Thay tọa độ các điểm $A, B, C$ vào phương trình, ta được hệ phương trình:  $$\\heva{&{1}+{4}+a+{2}b+c={0} <br>&{1}+{1}-a+b+c={0} <br>&{9}+{1}+{3}a-b+c={0}} \\Leftrightarrow \\heva{&a+{2}b+c=-{5} <br>&-a+b+c=-{2} <br>&{3}a-b+c=-{10}}$$  Giải hệ phương trình trên, ta được: $a=-\\dfrac{{7}}{{4}}$, $b=\\dfrac{{1}}{{2}}$, $c=-\\dfrac{{17}}{{4}}$.<br>Tọa độ tâm $I\\left(-\\dfrac{a}{2};-\\dfrac{b}{2}\\right) = \\left(\\dfrac{{7}}{{8}};-\\dfrac{{1}}{{4}}\\right)$.<br>Tổng hoành độ và tung độ của tâm $I$ là: $x+y = \\dfrac{{7}}{{8}} + \\left(-\\dfrac{{1}}{{4}}\\right) = \\dfrac{{5}}{{8}}$."}]}, {"noiDungChung": "Cho hình chóp $S.ABCD$ có đáy là hình vuông tâm $O$, cạnh bằng $a$. Tam giác $SAB$ đều và nằm trong mặt phẳng vuông góc với đáy. Gọi $H$ là trung điểm của $AB$, $N$ là trung điểm của $AD$.", "cauHoi": [{"question": "Hình chiếu vuông góc của $S$ lên $(ABCD)$ là điểm", "choices": ["$H$", "$O$", "$N$", "$A$"], "correctIndex": 0, "explain": "\\begin{center}  \\begin{tikzpicture}[scale=1.2, line cap=round, line join=round]  \\coordinate (A) at (0,0);  \\coordinate (B) at (3,-1.5);  \\coordinate (C) at (6.5,-1.5);  \\coordinate (D) at (3.5,0); <br>\\coordinate (H) at ($(A)!0.5!(B)$);  \\coordinate (N) at ($(A)!0.5!(D)$);  \\coordinate (S) at ($(H)+(0,3.8)$);<br>\\draw[dashed, thin] (A) -- (D);  \\draw[dashed, thin] (D) -- (C);  \\draw (S) -- (H);  \\draw[dashed, thin] (A) -- (C);  \\draw[dashed, thin] (B) -- (D); <br>\\coordinate (O) at (intersection of A--C and B--D);<br>\\draw[thick] (S) -- (A);  \\draw[thick] (S) -- (B);  \\draw[thick] (S) -- (C);  \\draw[thick] (A) -- (B);  \\draw[thick] (B) -- (C);  \\draw[dashed] (S) -- (D);<br>\\fill (A) circle (1.5pt) node[left] {$A$};  \\fill (B) circle (1.5pt) node[below] {$B$};  \\fill (C) circle (1.5pt) node[right] {$C$};  \\fill (D) circle (1.5pt) node[above] {$D$};  \\fill (S) circle (1.5pt) node[above] {$S$};  \\fill (H) circle (1.2pt) node[below left] {$H$};  \\fill (N) circle (1.2pt) node[above right] {$N$};  \\fill (O) circle (1.2pt) node[above right] {$O$};<br>\\draw[thin] ($(H)+(0,0.15)$) -- ($(H)+(0.15,0.15)$) -- ($(H)+(0.15,0)$);<br>\\end{tikzpicture}  \\end{center}  Ta có:<br>- $(SAB)\\perp(ABCD)$  <br>- $(SAB)\\cap(ABCD)=AB$  <br>- Trong $\\Delta SAB$ đều, $H$ là trung điểm $AB$ nên $SH\\perp AB$.<br>Từ đó suy ra $SH\\perp(ABCD)$.<br>Vậy hình chiếu vuông góc của $S$ lên mặt phẳng $(ABCD)$ chính là điểm $H$."}, {"question": "Phát biểu nào sau đây sai?", "choices": ["$d(D;(SAC))=d(H;(SAC))$", "$d(D;(SAC))=d(B;(SAC))$", "$V_{S.ABCD}=\\dfrac{a^{3}\\sqrt{{3}}}{{6}}$", "$SH=\\dfrac{a\\sqrt{{3}}}{{2}}$"], "correctIndex": 0, "explain": "Kiểm tra từng phát biểu:<br>- Phát biểu D: Tam giác $SAB$ đều cạnh $a$, đường cao $SH=\\dfrac{a\\sqrt{{3}}}{{2}}$. $\\Rightarrow$ Đúng.  <br>- Phát biểu C: Thể tích khối chóp $V_{S.ABCD}=\\dfrac{{1}}{{3}}\\cdot S_{ABCD}\\cdot SH=\\dfrac{{1}}{{3}}\\cdot a^{2}\\cdot\\dfrac{a\\sqrt{{3}}}{{2}}=\\dfrac{a^{3}\\sqrt{{3}}}{{6}}$. $\\Rightarrow$ Đúng.  <br>- Phát biểu B: Vì $O$ là trung điểm của $BD$ và $O\\in(SAC)$ nên khoảng cách từ $B$ và $D$ đến mặt phẳng $(SAC)$ là bằng nhau: $d(D;(SAC))=d(B;(SAC))$. $\\Rightarrow$ Đúng.  <br>- Phát biểu A: Đường thẳng $AB$ cắt $(SAC)$ tại $A$, do đó:  $$\\dfrac{d(H;(SAC))}{d(B;(SAC))}=\\dfrac{HA}{BA}=\\dfrac{{1}}{{2}}$$<br>Suy ra $d(H;(SAC))=\\dfrac{{1}}{{2}}d(B;(SAC))=\\dfrac{{1}}{{2}}d(D;(SAC))$.<br>Do đó, $d(D;(SAC))\\neq d(H;(SAC))$. $\\Rightarrow$ Sai."}, {"question": "Khoảng cách từ $D$ đến mặt phẳng $(SAC)$ là bao nhiêu?", "choices": ["$\\dfrac{a\\sqrt{{21}}}{{14}}$", "$\\dfrac{a\\sqrt{{21}}}{{28}}$", "$\\dfrac{a\\sqrt{{21}}}{{7}}$", "$\\dfrac{a\\sqrt{{2}}}{{2}}$"], "correctIndex": 2, "explain": "Từ chứng minh ở câu trên, ta có: $d(D;(SAC))={2}\\cdot d(H;(SAC))$.<br>Ta đi tính $d(H;(SAC))$:<br>Kẻ $HK\\perp AC$ tại $K$, và kẻ $HI\\perp SK$ tại $I$.<br>Ta có:  $$\\heva{&AC\\perp HK<br>&AC\\perp SH\\text{ (do }SH\\perp(ABCD))}\\Rightarrow AC\\perp(SHK)\\Rightarrow AC\\perp HI$$  Mặt khác $HI\\perp SK$, suy ra $HI\\perp(SAC)$. Vậy $d(H;(SAC))=HI$.<br>Xét trong mặt đáy $ABCD$, $O$ là giao điểm hai đường chéo nên $BO\\perp AC$.<br>Trong tam giác $ABO$ vuông tại $O$, $H$ là trung điểm $AB$, $HK\\parallel BO$ (cùng vuông góc với $AC$ nên $HK$ là đường trung bình.  $$\\Rightarrow HK=\\dfrac{{1}}{{2}}BO=\\dfrac{{1}}{{2}}\\left(\\dfrac{a\\sqrt{{2}}}{{2}}\\right)=\\dfrac{a\\sqrt{{2}}}{{4}}$$  Xét tam giác $SHK$ vuông tại $H$, có đường cao $HI$:  $$\\dfrac{{1}}{HI^{2}}=\\dfrac{{1}}{SH^{2}}+\\dfrac{{1}}{HK^{2}}=\\dfrac{{1}}{\\left(\\dfrac{a\\sqrt{{3}}}{{2}}\\right)^{2}}+\\dfrac{{1}}{\\left(\\dfrac{a\\sqrt{{2}}}{{4}}\\right)^{2}}=\\dfrac{{4}}{{3}a^{2}}+\\dfrac{{16}}{{2a^{2}}}=\\dfrac{{28}}{{3}a^{2}}\\Rightarrow HI=\\dfrac{a\\sqrt{{3}}}{{2}\\sqrt{{7}}}=\\dfrac{a\\sqrt{{21}}}{{14}}$$  Vậy khoảng cách cần tìm là: $d(D;(SAC))={2}\\cdot HI={2}\\cdot\\dfrac{a\\sqrt{{21}}}{{14}}=\\dfrac{a\\sqrt{{21}}}{{7}}$."}]}, {"noiDungChung": "Cho hàm số $y=\\dfrac{-mx+1}{x-m}$.", "cauHoi": [{"question": "Với $m={2}$ thì giá trị lớn nhất của hàm số trên ${[{3};{5}]}$ là", "choices": ["$-{2}$", "$-{1}$", "${3}$", "$-{3}$"], "correctIndex": 3, "explain": "Thay $m={2}$ vào hàm số, ta có $y=\\dfrac{-{2}x+{1}}{x-{2}}$.<br>Tập xác định: $D=\\mathbb{R}\\setminus\\{{2}\\}$.<br>Đoạn ${[{3};{5}]}$ nằm trọn trong tập xác định.<br>Ta tính đạo hàm:  $$y'=\\dfrac{-{3}}{(x-{2})^{2}}>{0},\\forall x\\in{[{3};{5}]}$$  Vì $y'>0$ nên hàm số đồng biến trên đoạn ${[{3};{5}]}$.<br>Do đó, giá trị lớn nhất của hàm số trên đoạn này đạt được tại $x={5}$: $\\max\\limits_{[{3};{5}]}y=y({5})=\\dfrac{-{2}({5})+{1}}{{5}-{2}}=\\dfrac{-{9}}{{3}}=-{3}$"}, {"question": "Với giá trị nào của tham số $m$ thì hàm số đồng biến trên từng khoảng xác định?", "choices": ["$m\\in(-\\infty;-{1})\\cup({1};+\\infty)$", "$m\\in(-\\infty;{0})\\cup({5};+\\infty)$", "$m\\in(-\\infty;-{2})\\cup({1};+\\infty)$", "$m\\in(-\\infty;{0})\\cup({1};+\\infty)$"], "correctIndex": 0, "explain": "Tập xác định: $D=\\mathbb{R}\\setminus\\{m\\}$.<br>$y'=\\dfrac{m^{2}-{1}}{(x-m)^{2}}$<br>Để hàm số đồng biến trên từng khoảng xác định, ta cần có $y'>0,\\forall x\\in D$:  $$\\Leftrightarrow m^{2}-{1}>{0}\\Leftrightarrow\\hoac{&m>{1}<br>&m<-{1}}\\Rightarrow m\\in(-\\infty;-{1})\\cup({1};+\\infty)$$"}, {"question": "Khi $m$ thay đổi trong $({3};+\\infty)$ thì đồ thị hàm số đi qua mấy điểm cố định?", "choices": ["${2}$ điểm", "${1}$ điểm", "${0}$ điểm", "${4}$ điểm"], "correctIndex": 0, "explain": "Gọi $M(x_{{0}};y_{{0}})$ là điểm cố định mà đồ thị hàm số luôn đi qua. Khi đó, phương trình sau phải đúng với mọi $m\\in({3};+\\infty)$ (lưu ý điều kiện $x_{{0}}\\neq m$):  $$y_{{0}}=\\dfrac{-mx_{{0}}+{1}}{x_{{0}}-m}\\Leftrightarrow y_{{0}}(x_{{0}}-m)=-mx_{{0}}+{1}\\Leftrightarrow x_{{0}}y_{{0}}-my_{{0}}=-mx_{{0}}+{1}\\Leftrightarrow m(x_{{0}}-y_{{0}})+(x_{{0}}y_{{0}}-{1})={0},\\forall m\\in({3};+\\infty)$$  Để phương trình đúng với mọi $m$, các hệ số phải đồng thời bằng ${0}$:  $$\\heva{&x_{{0}}-y_{{0}}={0}<br>&x_{{0}}y_{{0}}-{1}={0}}\\Leftrightarrow\\heva{&y_{{0}}=x_{{0}}<br>&x_{{0}}^{2}={1}}\\Leftrightarrow\\hoac{\\heva{&x_{{0}}={1}<br>&y_{{0}}={1}}<br>\\heva{&x_{{0}}=-{1}<br>&y_{{0}}=-{1}}}$$  Kiểm tra điều kiện $x_{{0}}\\neq m$: Vì $m\\in({3};+\\infty)$ nên $m$ không thể bằng ${1}$ hoặc $-{1}$. Do đó cả hai điểm $({1};{1})$ và $(-{1};-{1})$ đều luôn thỏa mãn và nằm trên đồ thị.<br>Vậy đồ thị hàm số đi qua ${2}$ điểm cố định."}]}, {"noiDungChung": "Trong ${7}$ ngày, một công ty sắp xếp chỗ cho ${5}$ nhân viên $M$, $N$, $P$, $Q$, $R$ tham gia các khóa huấn luyện. Mỗi nhân viên sẽ được huấn luyện trong ${1}$ ngày, ${2}$ nhân viên khác nhau sẽ được huấn luyện trong ${2}$ ngày khác nhau. Ngoài ra các khóa huấn luyện được tổ chức tuân thủ các điều kiện sau:<br>- Không có nhân viên nào tham gia huấn luyện vào ngày thứ ${6}$.  <br>- $R$ phải được tham gia huấn luyện trước $N$.  <br>- $M$ được huấn luyện ở ngày ngay trước ngày mà $Q$ được huấn luyện (cặp $(M, Q)$).  <br>- $P$ là người thứ ${3}$ được huấn luyện.", "cauHoi": [{"question": "Nếu $P$ được xếp vào ngày thứ ${4}$, thì điều nào sau đây phải đúng:", "choices": ["M được huấn luyện ở ngày thứ nhất", "Ngày thứ ${3}$ không có ai được huấn luyện", "R được huấn luyện vào ngày thứ ${5}$", "M được huấn luyện ở ngày thứ ${2}$"], "correctIndex": 2, "explain": "Theo giả thiết bổ sung của câu hỏi, $P$ (người thứ $3$ theo thứ tự học) được xếp vào ngày thứ ${4}$ trong tuần. Kết hợp với việc ngày thứ $6$ không có ai học và cặp $(M, Q)$ học liền nhau, ta xác định được lịch trình thỏa mãn các điều kiện, trong đó $R$ phải được huấn luyện vào ngày thứ ${5}$."}, {"question": "$R$ có thể được huấn luyện vào ngày nào?", "choices": ["Thứ ${7}$", "Thứ ${2}$", "Thứ ${3}$", "Thứ ${4}$"], "correctIndex": 3, "explain": "Dựa vào các ràng buộc về thứ tự ($R$ trước $N$, $P$ là người thứ $3$ học, và ngày thứ $6$ trống), $R$ có thể được sắp xếp huấn luyện vào ngày thứ ${4}$."}, {"question": "Ngày nào sau đây phải có ${1}$ nhân viên được huấn luyện", "choices": ["Thứ ${2}$", "Thứ ${3}$", "Thứ ${4}$", "Thứ nhất"], "correctIndex": 0, "explain": "Dựa trên tổng số ${5}$ nhân viên phân bổ trong $7$ ngày (với ngày thứ $6$ không có ai và các điều kiện trật tự cứng), ngày thứ ${2}$ luôn bắt buộc phải có nhân viên tham gia huấn luyện."}]}, {"noiDungChung": "Một biên tập viên sẽ biên tập ${7}$ bài viết, mỗi lần một bài, có ${3}$ bài viết $G$, $H$ và $J$ thuộc chủ đề Tài chính; ${3}$ bài viết khác $Q$, $R$ và $S$ thuộc chủ đề Dinh dưỡng; và bài viết còn lại là $Y$ thì thuộc chủ đề Động vật hoang dã. Thứ tự biên tập các bài viết phải tuân theo các điều kiện sau:<br>- Các bài viết liên tiếp không được thuộc cùng một chủ đề.  <br>- $S$ chỉ có thể được biên tập trước $Q$ nếu $Q$ là bài viết thứ ba được biên tập. (Tức là nếu $Q$ không xếp thứ $3$ thì bắt buộc $Q$ phải xếp trước $S$).  <br>- $S$ phải được biên tập trước $Y$.  <br>- $J$ phải được biên tập trước $G$ và $G$ phải được biên tập trước $R$.", "cauHoi": [{"question": "Đâu là thứ tự biên tập có thể đúng?", "choices": ["$J, Q, S, G, H, Y, R$", "$Q, J, S, H, Y, G, R$", "$Q, G, S, H, Y, J, R$", "$Q, J, Y, H, S, G, R$"], "correctIndex": 1, "explain": "Ký hiệu các chủ đề: Tài chính (T), Dinh dưỡng (D), Động vật (W). Ta kiểm tra các phương án:<br>- Phương án $J, Q, S, G, H, Y, R$ sai vì $G$ và $H$ (cùng chủ đề T) xếp liền nhau.  <br>- Phương án $Q, G, S, H, Y, J, R$ sai vì $G$ xếp trước $J$ (trái điều kiện $J$ trước $G$).  <br>- Phương án $Q, J, Y, H, S, G, R$ sai vì $Y$ xếp trước $S$ (trái điều kiện $S$ trước $Y$).  <br>- Phương án $Q, J, S, H, Y, G, R$ thỏa mãn tất cả các điều kiện: chủ đề xen kẽ (D-T-D-T-W-T-D); $J$ trước $G$ trước $R$; $S$ trước $Y$; và do $Q$ xếp trước $S$ nên không vi phạm ràng buộc vị trí của cặp $S, Q$."}, {"question": "Nếu $G$ là bài viết thứ tư được biên tập, khẳng định có thể đúng là", "choices": ["$J$ là bài viết thứ nhất được biên tập", "$Q$ là bài viết thứ hai được biên tập", "$S$ là bài viết thứ năm được biên tập", "$Y$ là bài viết thứ sáu được biên tập"], "correctIndex": 3, "explain": "Giả sử $Y$ xếp thứ $6$, ta có thể thiết lập một thứ tự hoàn toàn hợp lệ như sau: $S(1), J(2), Q(3), G(4), R(5), Y(6), H(7)$.<br>- Các chủ đề phân bổ xen kẽ hợp lý: Dinh dưỡng (1, 3, 5), Tài chính (2, 4, 7) và Động vật (6).  <br>- $J(2)$ trước $G(4)$ trước $R(5)$.  <br>- $S(1)$ trước $Y(6)$.  <br>- $S(1)$ xếp trước $Q(3)$, và $Q$ nằm đúng vị trí thứ $3$ (thỏa mãn trọn vẹn điều kiện của cặp này).<br>Do đó, trường hợp $Y$ là bài viết thứ sáu hoàn toàn có thể xảy ra."}, {"question": "Thứ tự biên tập ${7}$ bài viết có thể được xác định hoàn toàn nếu như", "choices": ["$R$ là bài viết thứ bảy được biên tập", "$R$ là bài viết thứ tư được biên tập", "$H$ là bài viết thứ sáu được biên tập", "$H$ là bài viết thứ tư được biên tập"], "correctIndex": 1, "explain": "Nếu $R$ (Dinh dưỡng) xếp thứ $4$:<br>- Vì $J < G < R$ nên $J, G$ (cùng là Tài chính) phải nằm trong $3$ vị trí đầu. Để không trùng chủ đề liền kề, buộc $J=1$ và $G=3$.  <br>- Vị trí số $2$ không thể là $Y$ vì $S$ phải đứng trước $Y$ (nếu $Y=2 \\implies S=1$, mâu thuẫn vì vị trí $1$ đã là $J$). Do đó, vị trí số $2$ phải là bài Dinh dưỡng ($Q$ hoặc $S$).  <br>- Các vị trí $5, 6, 7$ dành cho $H$ (Tài chính), $Y$ (Động vật) và $1$ bài Dinh dưỡng còn lại. Để Dinh dưỡng không trùng với $R(4)$, bài Dinh dưỡng này phải ở vị trí $6$.  <br>- Vậy $2$ bài Dinh dưỡng nằm ở vị trí $2$ và $6$. Do không có bài nào ở vị trí số $3$, $S$ không thể đứng trước $Q$, buộc $Q < S$. Suy ra $Q=2, S=6$.  <br>- Vì $S < Y$ nên $Y$ phải ở vị trí $7$, suy ra vị trí số $5$ thuộc về $H$.<br>Thứ tự được xác định duy nhất và hoàn toàn là: $J, Q, G, R, H, S, Y$."}]}, {"noiDungChung": "Bảng sau thể hiện sản lượng của một doanh nghiệp gồm các công ty con<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Năm}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>M}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>N}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>P}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Q}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>R}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>S}</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>2016}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${150}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${75}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${58}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${48}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${49}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${32}$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>2017}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${137}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${68}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${67}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${61}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${45}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${28}$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>2018}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${160}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${65}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${82}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${59}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${46}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${37}$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>2019}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${168}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${70}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${45}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${75}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${43}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${35}$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>2020}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${180}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${55}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${80}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${67}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${47}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${28}$</td></tr></table>", "cauHoi": [{"question": "Từ năm ${2016}$ đến năm ${2020}$, năm nào có tổng sản lượng tăng cao nhất", "choices": ["${2020}$", "${2016}$", "${2018}$", "${2019}$"], "correctIndex": 0, "explain": "Tổng sản lượng của các công ty trong từng năm là:<br>- Năm ${2016}$: $150 + 75 + 58 + 48 + 49 + 32 = 412$.  <br>- Năm ${2017}$: $137 + 68 + 67 + 61 + 45 + 28 = 406$.  <br>- Năm ${2018}$: $160 + 65 + 82 + 59 + 46 + 37 = 449$.  <br>- Năm ${2019}$: $168 + 70 + 45 + 75 + 43 + 35 = 436$.  <br>- Năm ${2020}$: $180 + 55 + 80 + 67 + 47 + 28 = 457$.<br>Vậy năm ${2020}$ có tổng sản lượng cao nhất ($457$)."}, {"question": "Tổng sản lượng của doanh nghiệp năm ${2020}$ tăng bao nhiêu phần trăm so với năm ${2016}$?", "choices": ["${10}{,}{9}\\%$", "${7}\\%$", "${9}{,}{1}\\%$", "${13}{,}{3}\\%$"], "correctIndex": 0, "explain": "Tổng sản lượng năm $2016$ là $412$ và năm $2020$ là $457$.<br>Tỷ lệ phần trăm tăng trưởng từ năm $2016$ đến năm $2020$ là:  $$\\dfrac{457 - 412}{412} \\times 100\\% \\approx 10{,}92\\% \\approx 10{,}9\\%.$$"}, {"question": "Từ cuối năm ${2016}$ đến năm ${2020}$, công ty có tỷ lệ tăng cao nhất", "choices": ["$S$", "$P$", "$Q$", "$M$"], "correctIndex": 2, "explain": "Loại các công ty có sản lượng năm $2020$ giảm hoặc không tăng so với năm $2016$ ($N, R, S$). <br>Xét tốc độ tăng trưởng của các công ty còn lại:<br>- Công ty $M$: $\\dfrac{180 - 150}{150} \\times 100\\% = 20\\%$.  <br>- Công ty $P$: $\\dfrac{80 - 58}{58} \\times 100\\% \\approx 37{,}93\\%$.  <br>- Công ty $Q$: $\\dfrac{67 - 48}{48} \\times 100\\% \\approx 39{,}58\\%$.<br>Vậy công ty $Q$ có tỷ lệ tăng trưởng cao nhất."}]}, {"noiDungChung": "Biểu đồ thể hiện sản lượng xuất khẩu và nhập khẩu giai đoạn ${1995}-{2000}$<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.85]\n\t\t\n\t\t\\node[font=\\bfseries\\large] at (6, 7) {Giá trị xuất khẩu và nhập khẩu};\n\t\t\n\t\t\n\t\t\\foreach \\y/\\val in {0/0, 1/100, 2/200, 3/300, 4/400, 5/500, 6/600, 7/700} {\n\t\t\t\\draw[gray!40, dashed] (0, \\y) -- (12, \\y);\n\t\t\t\\node[left, font=\\small] at (0, \\y) {\\val};\n\t\t}\n\t\t\\draw[thick] (0, 0) -- (12, 0);\n\t\t\n\t\t\n\t\t\n\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (0.6, 0) rectangle (1.0, 0.2); \n\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (1.1, 0) rectangle (1.5, 1.2); \n\t\t\\node[above, font=\\tiny] at (0.8, 0.2) {20};\n\t\t\\node[above, font=\\tiny] at (1.3, 1.2) {120};\n\t\t\\node[below, font=\\small] at (1.05, 0) {1995};\n\t\t\n\t\t\n\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (2.6, 0) rectangle (3.0, 1.25); \n\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (3.1, 0) rectangle (3.5, 3.0); \n\t\t\\node[above, font=\\tiny] at (2.8, 1.25) {125};\n\t\t\\node[above, font=\\tiny] at (3.3, 3.0) {300};\n\t\t\\node[below, font=\\small] at (3.05, 0) {1996};\n\t\t\n\t\t\n\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (4.6, 0) rectangle (5.0, 3.75); \n\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (5.1, 0) rectangle (5.5, 5.0); \n\t\t\\node[above, font=\\tiny] at (4.8, 3.75) {375};\n\t\t\\node[above, font=\\tiny] at (5.3, 5.0) {500};\n\t\t\\node[below, font=\\small] at (5.05, 0) {1997};\n\t\t\n\t\t\n\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (6.6, 0) rectangle (7.0, 3.3); \n\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (7.1, 0) rectangle (7.5, 4.0); \n\t\t\\node[above, font=\\tiny] at (6.8, 3.3) {330};\n\t\t\\node[above, font=\\tiny] at (7.3, 4.0) {400};\n\t\t\\node[below, font=\\small] at (7.05, 0) {1998};\n\t\t\n\t\t\n\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (8.6, 0) rectangle (9.0, 5.25); \n\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (9.1, 0) rectangle (9.5, 6.0); \n\t\t\\node[above, font=\\tiny] at (8.8, 5.25) {525};\n\t\t\\node[above, font=\\tiny] at (9.3, 6.0) {600};\n\t\t\\node[below, font=\\small] at (9.05, 0) {1999};\n\t\t\n\t\t\n\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (10.6, 0) rectangle (11.0, 4.75); \n\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (11.1, 0) rectangle (11.5, 5.25); \n\t\t\\node[above, font=\\tiny] at (10.8, 4.75) {475};\n\t\t\\node[above, font=\\tiny] at (11.3, 5.25) {525};\n\t\t\\node[below, font=\\small] at (11.05, 0) {2000};\n\t\t\n\t\t\n\t\t\\begin{scope}[shift={(3.5, -1.2)}]\n\t\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (0, 0) rectangle (-0.3, 0.2);\n\t\t\t\\node[right, font=\\small] at (0, 0.1) {Xuất khẩu};\n\t\t\t\n\t\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (2.5, 0) rectangle (3, 0.2);\n\t\t\t\\node[right, font=\\small] at (3, 0.1) {Nhập khẩu};\n\t\t\\end{scope}\n\t\t\n\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Trong ${4}$ năm ${1995}$, ${1996}$, ${1998}$, ${1999}$, năm nào có độ chênh lệch giữa nhập khẩu và xuất khẩu lớn nhất?", "choices": ["${1996}$", "${1995}$", "${1998}$", "${1999}$"], "correctIndex": 0, "explain": "Độ chênh lệch giữa nhập khẩu và xuất khẩu trong các năm là:<br>- Năm ${1995}$: $|120 - 20| = 100$.  <br>- Năm ${1996}$: $|300 - 125| = 175$.  <br>- Năm ${1998}$: $|400 - 330| = 70$.  <br>- Năm ${1999}$: $|600 - 525| = 75$.<br>Vậy năm ${1996}$ có độ chênh lệch lớn nhất ($175$)."}, {"question": "Sản lượng xuất khẩu của năm cao nhất chiếm khoảng bao nhiêu phần trăm so với tổng sản lượng nhập khẩu của ${3}$ năm ${1997}$, ${1998}$, ${1999}$?", "choices": ["${37}\\%$", "${49}\\%$", "${45}\\%$", "${33}\\%$"], "correctIndex": 1, "explain": "Sản lượng xuất khẩu cao nhất là $600$ (năm ${1999}$).<br>Tổng sản lượng nhập khẩu của ${3}$ năm ${1997}$, ${1998}$, ${1999}$ là:  $$375+330+525=1230.$$<br>Tỷ lệ phần trăm:  $$\\dfrac{600}{1230} \\times 100 \\% \\approx 48,78 \\%$$"}, {"question": "Từ năm ${1995}$ đến năm ${1999}$, tổng sản lượng (xuất khẩu + nhập khẩu) của năm nào tăng nhiều nhất so với năm trước?", "choices": ["${1996}$", "${1997}$", "${1998}$", "${1999}$"], "correctIndex": 0, "explain": "Tổng sản lượng (xuất khẩu + nhập khẩu) của các năm là:<br>- Năm ${1995}$: $20 + 120 = 140$.  <br>- Năm ${1996}$: $125 + 300 = 425$.  <br>- Năm ${1997}$: $375 + 500 = 875$.  <br>- Năm ${1998}$: $330 + 400 = 730$.  <br>- Năm ${1999}$: $525 + 600 = 1125$.<br>Mức tăng tuyệt đối so với năm trước:<br>- Năm ${1996}$: $425 - 140 = 285$.  <br>- Năm ${1997}$: $875 - 425 = 450$.  <br>- Năm ${1998}$: $730 - 875 = -145$ (giảm).  <br>- Năm ${1999}$: $1125 - 730 = 395$.<br>Nếu xét theo tốc độ tăng trưởng phần trăm:<br>- Năm ${1996}$: $\\dfrac{425 - 140}{140} \\times 100\\% \\approx 203{,}57\\%$.  <br>- Năm ${1997}$: $\\dfrac{875 - 425}{425} \\times 100\\% \\approx 105{,}88\\%$.<br>Vậy năm ${1996}$ có tỉ lệ phần trăm tăng trưởng so với năm trước lớn nhất."}]}]}, {"id": "de-2-2026", "ten": "Đề chính thức đợt 2 - 2026", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Cho phương trình $x^2 + 5x + m - m^2 = 0$. Các giá trị của $m$ để phương trình có $2$ nghiệm trái dấu là", "choices": ["$m > \\dfrac{1}{4}$", "$m < \\dfrac{29}{12}$", "$m \\in \\varnothing$", "$\\hoac{&m < 0 \\\\ &m > 1}$"], "correctIndex": 3, "explain": "Phương trình có $2$ nghiệm trái dấu khi và chỉ khi $ac < 0$  $$\\Leftrightarrow 1 \\cdot (m - m^2) < 0 \\Leftrightarrow m - m^2 < 0 \\Leftrightarrow \\hoac{&m < 0 <br>&m > 1}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho phương trình $x+\\sqrt{x+\\dfrac{1}{2}+\\sqrt{x+\\dfrac{1}{4}}}=m$ (với $m$ là tham số). Các giá trị của tham số $m$ để phương trình đã cho vô nghiệm là", "choices": ["$m<\\dfrac{1}{4}$", "$m\\in\\varnothing$", "$m>1$", "$0<m<\\dfrac{1}{4}$"], "correctIndex": 0, "explain": "Điều kiện xác định $x+\\dfrac{1}{4}\\ge 0\\Rightarrow x\\ge -\\dfrac{1}{4}$.<br>Ta xét biểu thức trong căn lớn:  $$x+\\dfrac{1}{2}+\\sqrt{x+\\dfrac{1}{4}}=\\left(x+\\dfrac{1}{4}\\right)+\\sqrt{x+\\dfrac{1}{4}}+\\dfrac{1}{4}=\\left(\\sqrt{x+\\dfrac{1}{4}}+\\dfrac{1}{2}\\right)^2$$<br>Lúc này, phương trình ban đầu trở thành:  $$x+\\sqrt{\\left(\\sqrt{x+\\dfrac{1}{4}}+\\dfrac{1}{2}\\right)^2}=m\\Leftrightarrow x+\\left|\\sqrt{x+\\dfrac{1}{4}}+\\dfrac{1}{2}\\right|=m$$<br>Vì $\\sqrt{x+\\dfrac{1}{4}}\\ge 0$ nên biểu thức trong trị tuyệt đối luôn dương. Ta có: $x+\\sqrt{x+\\dfrac{1}{4}}+\\dfrac{1}{2}=m$.<br>Đặt $t=\\sqrt{x+\\dfrac{1}{4}}$ (với $t\\ge 0$), ta có $x=t^2-\\dfrac{1}{4}$.<br>Thay vào vế trái ($VT$), ta được:  $$VT=\\left(t^2-\\dfrac{1}{4}\\right)+t+\\dfrac{1}{2}=t^2+t+\\dfrac{1}{4}=\\left(t+\\dfrac{1}{2}\\right)^2$$<br>Vì $t\\ge 0\\Rightarrow t+\\dfrac{1}{2}\\ge \\dfrac{1}{2}\\Rightarrow \\left(t+\\dfrac{1}{2}\\right)^2\\ge \\dfrac{1}{4}$.<br>Tức là vế trái luôn $\\ge \\dfrac{1}{4}$.<br>Để phương trình đã cho vô nghiệm, giá trị của $m$ phải nhỏ hơn giá trị nhỏ nhất của vế trái:  $$m<\\dfrac{1}{4}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho bất phương trình $2^x + x \\le y + \\log_2 y$ với $x, y \\in \\mathbb{Z}^+; y \\le 15$. Số giá trị $x$ thỏa mãn là", "choices": ["$5$", "$4$", "$3$", "$2$"], "correctIndex": 2, "explain": "Điều kiện: $y \\in \\mathbb{Z}^+$ và $y \\le 15$. <br>Biết rằng hàm số $f(t) = 2^t + t$ đồng biến trên $\\mathbb{R}$, bất phương trình đã cho được viết lại dưới dạng:  $$2^x + x \\le 2^{\\log_2 y} + \\log_2 y \\iff f(x) \\le f(\\log_2 y) \\iff x \\le \\log_2 y.$$<br>Vì $x \\in \\mathbb{Z}^+$ và $y \\le 15$ nên $\\log_2 y \\le \\log_2 15 \\approx 3{,}9$. <br>Do $x$ là số nguyên dương ($x \\ge 1$), các giá trị nguyên của $x$ thỏa mãn là $x \\in \\{1; 2; 3\\}$. <br>Với mỗi giá trị của $x$, ta chọn $y \\in \\mathbb{Z}^+$ sao cho $y \\le 15$ và $y \\ge 2^x$:<br>- $x = 1 \\implies 2 \\le y \\le 15$ (có $14$ giá trị $y$).  <br>- $x = 2 \\implies 4 \\le y \\le 15$ (có $12$ giá trị $y$).  <br>- $x = 3 \\implies 8 \\le y \\le 15$ (có $8$ giá trị $y$).<br>Vậy có tổng cộng $3$ giá trị của $x$ thỏa mãn bài toán."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết $2$ số $x$, $y$ thoả mãn $1+\\log_{2}x+\\log_{2}(x-2)=\\log_{2}y$. Mối quan hệ giữa $x$ và $y$ là", "choices": ["$y=2x-1$", "$y=2x$", "$y=2x^{2}-4x$", "$y=x^{2}-4x+4$"], "correctIndex": 2, "explain": "Điều kiện xác định: $\\heva{&x>0\\\\&x-2>0\\\\&y>0}\\Leftrightarrow\\heva{&x>2\\\\&y>0}$.<br>Phương trình đã cho tương đương với:  $$\\log_{2}2+\\log_{2}x+\\log_{2}(x-2)=\\log_{2}y$$  $$\\Leftrightarrow\\log_{2}\\big[2x(x-2)\\big]=\\log_{2}y$$  $$\\Leftrightarrow y=2x^{2}-4x\\quad\\text{(thỏa mãn điều kiện $x>2$ và $y>0$)}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trong $1$ lớp học có $20$ học sinh. Nếu $1$ cặp học sinh kết bạn với nhau thì được tính là $1$ kết nối. Số kết nối tối đa trong lớp là", "choices": ["$200$", "$180$", "$190$", "$170$"], "correctIndex": 2, "explain": "Mỗi kết nối giữa hai học sinh trong lớp ứng với việc chọn ra một tập hợp gồm $2$ học sinh từ tổng số $20$ học sinh.<br>Số kết nối tối đa chính là số tổ hợp chập $2$ của $20$ phần tử:  $$C_{20}^{2}=\\dfrac{20\\cdot 19}{2}=190$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một nhân viên giao hàng xuất phát từ kho $K$ đi giao hàng cho $4$ khách hàng ở $4$ địa chỉ $A$, $B$, $C$, $D$. Yêu cầu bắt buộc là phải ghé qua mỗi địa chỉ $1$ lần, sau đó về kho để kết thúc. Thời gian di chuyển cho trong đồ thị.   \\begin{center}<br>\\end{center}  Thời gian tối thiểu để hoàn thành là<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=3, font=\\footnotesize]\n\t\t\t\n\t\t\t\n\t\t\t\\def\\r{1}\n\t\t\t\\coordinate (D) at (90:\\r);\n\t\t\t\\coordinate (K) at (90+72:\\r);\n\t\t\t\\coordinate (A) at (90+2*72:\\r);\n\t\t\t\\coordinate (B) at (90+3*72:\\r);\n\t\t\t\\coordinate (C) at (90+4*72:\\r);\n\t\t\t\n\t\t\t\n\t\t\t\\draw (D) -- (K) -- (A) -- (B) -- (C) -- cycle;\n\t\t\t\n\t\t\t\n\t\t\t\\draw (D) -- (B);\n\t\t\t\\draw (D) -- (A);\n\t\t\t\\draw (K) -- (C);\n\t\t\t\\draw (K) -- (B);\n\t\t\t\\draw (A) -- (C);\n\t\t\t\n\t\t\t\n\t\t\t\n\t\t\t\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (D)!.5!(K) $) {35};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (K)!.5!(A) $) {18};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (A)!.5!(B) $) {10};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (B)!.5!(C) $) {25};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (C)!.5!(D) $) {30};\n\t\t\t\n\t\t\t\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (D)!.55!(B) $) {40};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (K)!.45!(C) $) {15};\n\t\t\t\n\t\t\t\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (D)!.4!(A) $) {12};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (A)!.55!(C) $) {32};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (K)!.6!(B) $) {8};\n\t\t\t\n\t\t\t\n\t\t\t\\node[above, yshift=2pt] at (D) {D};\n\t\t\t\\node[left, xshift=-2pt] at (K) {K};\n\t\t\t\\node[right, xshift=2pt] at (A) {A};\n\t\t\t\\node[right, xshift=2pt] at (B) {B};\n\t\t\t\\node[left, xshift=-2pt] at (C) {C};\n\t\t\t\n\t\t\\end{tikzpicture}</script></div>", "choices": ["$75$ phút", "$78$ phút", "$80$ phút", "$72$ phút"], "correctIndex": 0, "explain": "Bài toán yêu cầu tìm chu trình xuất phát từ $K$, đi qua tất cả các đỉnh $A, B, C, D$ mỗi đỉnh đúng một lần rồi quay lại $K$ sao cho tổng trọng số (thời gian di chuyển) là nhỏ nhất.<br>Từ đồ thị, trọng số các cạnh liên quan trực tiếp đến kho $K$ là:<br>- $KD = 35$  <br>- $KA = 18$  <br>- $KB = 8$  <br>- $KC = 15$<br>Để tổng thời gian là nhỏ nhất, ta ưu tiên chọn các cạnh xuất phát và kết thúc từ $K$ có trọng số nhỏ nhất là $KB = 8$ và $KA = 18$ (hoặc $KC = 15$).<br>Xét hành trình tối ưu $K \\to B \\to C \\to D \\to A \\to K$:<br>- $K \\to B$: $8$  <br>- $B \\to C$: $25$  <br>- $C \\to D$: $30$  <br>- $D \\to A$: $12$  <br>- $A \\to K$: $18$<br>Tổng thời gian của hành trình này là:  $$8 + 25 + 30 + 12 + 18 = 93 \\text{ (chưa tối ưu)}$$<br>Xét hành trình tối ưu khác $K \\to B \\to A \\to D \\to C \\to K$:<br>- $K \\to B$: $8$  <br>- $B \\to A$: $10$  <br>- $A \\to D$: $12$  <br>- $D \\to C$: $30$  <br>- $C \\to K$: $15$<br>Tổng thời gian của hành trình này là:  $$8 + 10 + 12 + 30 + 15 = 75 \\text{ phút}.$$<br>Kiểm tra các phương án khác, ta thấy $75$ phút là thời gian di chuyển tối thiểu."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ vuông cân tại $A$ có $BC=10$. Lấy điểm $M$ sao cho $MA=8$ và $MB=9$. Độ dài đoạn thẳng $MC$ là", "choices": ["$7{,}17$", "$5{,}8$", "$2{,}4$", "$1{,}82$"], "correctIndex": 2, "explain": "Tam giác $ABC$ vuông cân tại $A$ với cạnh huyền $BC=10$, ta tính được độ dài cạnh góc vuông:  $$AB = AC = \\dfrac{BC}{\\sqrt{2}} = 5\\sqrt{2}.$$<br>Chọn hệ trục tọa độ $Oxy$ sao cho $A(0;0)$, tia $AB$ nằm trên trục $Ox$ và tia $AC$ nằm trên trục $Oy$. Khi đó:  $$B(5\\sqrt{2}; 0) \\quad \\text{và} \\quad C(0; 5\\sqrt{2}).$$<br>Giả sử điểm $M(x; y)$. Từ giả thiết $MA = 8$ và $MB = 9$, ta có hệ phương trình:  $$\\heva{&x^2 + y^2 = 64 <br>&(x - 5\\sqrt{2})^2 + y^2 = 81}$$<br>Khai triển phương trình thứ hai và thay $x^2 + y^2 = 64$:  $$x^2 + y^2 - 10\\sqrt{2}x + 50 = 81 \\implies 64 - 10\\sqrt{2}x + 50 = 81 \\implies x = \\dfrac{33}{10\\sqrt{2}}.$$<br>Tiếp tục tính $y^2$:  $$y^2 = 64 - x^2 = 64 - \\dfrac{1089}{200} = \\dfrac{11711}{200} \\implies y = \\pm\\sqrt{\\dfrac{11711}{200}}.$$<br>Độ dài đoạn thẳng $MC$ được tính theo công thức:  $$MC^2 = x^2 + (y - 5\\sqrt{2})^2 = x^2 + y^2 - 10\\sqrt{2}y + 50 = 114 - 10\\sqrt{2}y.$$<br>Chọn nghiệm $y = \\sqrt{\\dfrac{11711}{200}}$ (điểm $M$ nằm cùng phía với $C$ đối với trục $Ox$), ta được:  $$MC^2 = 114 - 10\\sqrt{2} \\cdot \\sqrt{\\dfrac{11711}{200}} = 114 - \\sqrt{11711} \\approx 5{,}783 \\implies MC \\approx 2{,}4.$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $\\tan x=a$. Tính giá trị biểu thức $A=\\dfrac{4+6\\cos^{2}x}{3\\sin^{2}x+1}$", "choices": ["$\\dfrac{a^{2}-1}{a^{2}+1}$", "$\\dfrac{4a^{2}+6}{3a^{2}+1}$", "$\\dfrac{4a^{2}+10}{4a^{2}+1}$", "$\\dfrac{a^{2}}{2}$"], "correctIndex": 2, "explain": "Chia cả tử và mẫu cho $\\cos^{2}x$, ta được:  $$A=\\dfrac{\\dfrac{4+6\\cos^{2}x}{\\cos^{2}x}}{\\dfrac{3\\sin^{2}x+1}{\\cos^{2}x}}=\\dfrac{\\dfrac{4}{\\cos^{2}x}+6}{3\\tan^{2}x+\\dfrac{1}{\\cos^{2}x}}=\\dfrac{4(1+\\tan^{2}x)+6}{3\\tan^{2}x+(1+\\tan^{2}x)}=\\dfrac{4a^{2}+10}{4a^{2}+1}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tính giới hạn $\\lim\\limits_{x\\to-2}\\dfrac{x^{3}+2x^{2}-1}{5-3x}$", "choices": ["$\\dfrac{1}{2}$", "$-\\dfrac{3}{5}$", "$0$", "$-\\dfrac{1}{11}$"], "correctIndex": 3, "explain": "$$\\lim\\limits_{x\\to-2}\\dfrac{x^{3}+2x^{2}-1}{5-3x}=\\dfrac{(-2)^{3}+2(-2)^{2}-1}{5-3(-2)}=\\dfrac{-8+8-1}{5+6}=-\\dfrac{1}{11}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Đồ thị hàm số $y=\\dfrac{2x^{2}-x+1}{x^{2}-1}$ có bao nhiêu đường tiệm cận?", "choices": ["$1$", "$4$", "$2$", "$3$"], "correctIndex": 3, "explain": "Ta có $\\lim\\limits_{x\\to\\pm\\infty}y=\\lim\\limits_{x\\to\\pm\\infty}\\dfrac{2-\\dfrac{1}{x}+\\dfrac{1}{x^{2}}}{1-\\dfrac{1}{x^{2}}}=2$, nên đồ thị hàm số có $1$ tiệm cận ngang là $y=2$.<br>Mặt khác $\\lim\\limits_{x\\to 1^{\\pm}}y=\\pm\\infty$ và $\\lim\\limits_{x\\to-1^{\\pm}}y=\\pm\\infty$, nên đồ thị hàm số có $2$ tiệm cận đứng là $x=1$ và $x=-1$.<br>Vậy đồ thị hàm số có tổng cộng $3$ đường tiệm cận."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hàm số $f(x)$ có đạo hàm liên tục trên khoảng $(0;+\\infty)$ và thoả mãn hệ thức $x\\cdot f'(x)-f(x)=2$ với mọi $x>0$. Biết rằng $f(1)=0$. Giá trị của $f(2)$ bằng:", "choices": ["$2$", "$4$", "$0$", "$-2$"], "correctIndex": 0, "explain": "Biến đổi phương trình đã cho với $x>0$:  $$x\\cdot f'(x)-f(x)=2\\Leftrightarrow\\dfrac{x\\cdot f'(x)-f(x)}{x^{2}}=\\dfrac{2}{x^{2}}\\Leftrightarrow\\left(\\dfrac{f(x)}{x}\\right)'=\\dfrac{2}{x^{2}}$$  Lấy nguyên hàm hai vế:  $$\\dfrac{f(x)}{x}=\\int\\dfrac{2}{x^{2}}\\mathrm{d}x=-\\dfrac{2}{x}+C$$  Với $f(1)=0$, ta có $\\dfrac{f(1)}{1}=-\\dfrac{2}{1}+C\\Leftrightarrow 0=-2+C\\Leftrightarrow C=2$.<br>Do đó $\\dfrac{f(x)}{x}=-\\dfrac{2}{x}+2\\Leftrightarrow f(x)=-2+2x$.<br>Vậy $f(2)=-2+2(2)=2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Giá trị của $A=\\displaystyle\\int \\limits_{-2}^{2}|x-1|\\mathrm{d}x$ là:", "choices": ["$4$", "$2$", "$5$", "$-4$"], "correctIndex": 2, "explain": "Ta phân tích tích phân dựa vào nghiệm của biểu thức trong dấu giá trị tuyệt đối ($x=1$):  $$A=\\displaystyle\\int \\limits_{-2}^{1}(1-x)\\mathrm{d}x+\\displaystyle\\int \\limits_{1}^{2}(x-1)\\mathrm{d}x=\\left.\\left(x-\\dfrac{x^{2}}{2}\\right)\\right|_{-2}^{1}+\\left.\\left(\\dfrac{x^{2}}{2}-x\\right)\\right|_{1}^{2}$$  $$=\\left[\\left(1-\\dfrac{1}{2}\\right)-\\left(-2-\\dfrac{4}{2}\\right)\\right]+\\left[\\left(\\dfrac{4}{2}-2\\right)-\\left(\\dfrac{1}{2}-1\\right)\\right]=\\left(\\dfrac{1}{2}+4\\right)+\\left(0+\\dfrac{1}{2}\\right)=5$$"}]}, {"noiDungChung": "Một chai tương ớt được sản xuất với $2$ thành phần là ớt và cà chua, khối lượng phụ gia không đáng kể, hao hụt ở dây chuyền bằng $0$. Một công ty sản xuất tương ớt theo định lượng $1\\text{ kg/chai}$ và chia thành $2$ loại:<br>- Loại cao cấp: Chứa $40\\%$ ớt tươi. Giá bán: $90$ nghìn đồng/chai.  <br>- Loại tiêu chuẩn: Chứa $25\\%$ ớt tươi. Giá bán: $30$ nghìn đồng/chai.<br>Kho đang có sẵn $2$ tấn ớt tươi và $3$ tấn cà chua.", "cauHoi": [{"question": "Nếu sản xuất $x$ chai tương ớt cao cấp và $y$ chai tiêu chuẩn thì khối lượng cà chua được sử dụng (tính theo $\\text{kg}$) là:", "choices": ["$0{,}4x + 0{,}1y$", "$0{,}4x + 0{,}25y$", "$1{,}5x + 3y$", "$0{,}6x + 0{,}75y$"], "correctIndex": 3, "explain": "Mỗi chai tương ớt có khối lượng $1\\text{ kg}$. <br>Mỗi chai loại cao cấp chứa $40\\%$ ớt nên chứa $60\\%$ ($0{,}6\\text{ kg}$) cà chua. Chai loại tiêu chuẩn chứa $25\\%$ ớt nên chứa $75\\%$ ($0{,}75\\text{ kg}$) cà chua.<br>Tổng khối lượng cà chua được sử dụng cho $x$ chai cao cấp và $y$ chai tiêu chuẩn là:  $$0{,}6x + 0{,}75y \\text{ (kg).}$$"}, {"question": "Tổng số chai tương ớt $2$ loại cần sản xuất để thu được doanh thu lớn nhất là:", "choices": ["$4000$", "$5000$", "$4800$", "$5250$"], "correctIndex": 1, "explain": "\\begin{center}  \\begin{tikzpicture}[scale=0.9, >=stealth]<br>\\draw[step=1cm, gray!30, dashed] (-1,-1) grid (6,5);  \\draw[->, thick] (-1,0) -- (6,0) node[below] {$x$};  \\draw[->, thick] (0,-1) -- (0,5) node[above] {$y$};<br>\\foreach \\x/\\xtext in {1/1000, 2/2000, 3/3000, 4/4000, 5/5000}  \\draw (\\x, 0.1) -- (\\x, -0.1) node[below, font=\\footnotesize] {\\xtext};  \\foreach \\y/\\ytext in {1/1000, 2/2000, 3/3000, 4/4000}  \\draw (0.1, \\y) -- (-0.1, \\y) node[left, font=\\footnotesize] {\\ytext};  \\node[below left, font=\\footnotesize] at (0,0) {$0$};<br>\\fill[gray, opacity=0.3] (0,0) -- (0,4) -- (3,3.2) -- (5,0) -- cycle;<br>\\draw[blue, thick] (0,4) -- (3,3.2) node[above right, sloped, font=\\footnotesize] {$0{,}6x+0{,}75y=3000$};  \\draw[red, thick] (3,3.2) -- (5,0) node[above right, sloped, font=\\footnotesize] {$0{,}4x+0{,}25y=2000$};  \\draw[thick] (0,0) -- (0,4);  \\draw[thick] (0,0) -- (5,0);<br>\\filldraw (0,0) circle (2pt) node[below left, font=\\footnotesize] {$O$};  \\filldraw (0,4) circle (2pt) node[above left, font=\\footnotesize] {$A$};  \\filldraw (3,3.2) circle (2pt) node[below right, xshift=4mm, font=\\footnotesize] {$B$};  \\filldraw (5,0) circle (2pt) node[above left , xshift=3mm, font=\\footnotesize] {$C$};<br>\\end{tikzpicture}  \\end{center}  Đổi $2\\text{ tấn} = 2000\\text{ kg}$ ớt tươi, $3\\text{ tấn} = 3000\\text{ kg}$ cà chua. Ta có hệ bất phương trình:  $$\\heva{&0{,}4x + 0{,}25y \\le 2000 <br>&0{,}6x + 0{,}75y \\le 3000 <br>&x \\ge 0, \\, y \\ge 0}$$<br>Hàm doanh thu cần đạt giá trị lớn nhất: $F(x, y) = 90x + 30y$ (nghìn đồng).<br>Miền nghiệm là tứ giác $OABC$ với các đỉnh: $O(0; 0)$, $A(0; 4000)$, $B(2500; 2000)$, $C(5000; 0)$.<br>Thay tọa độ các đỉnh vào hàm mục tiêu $F(x, y)$:<br>- Tại $O(0; 0): F = 0$.  <br>- Tại $A(0; 4000): F = 30 \\cdot 4000 = 120000$.  <br>- Tại $B(2500; 2000): F = 90 \\cdot 2500 + 30 \\cdot 2000 = 285000$.  <br>- Tại $C(5000; 0): F = 90 \\cdot 5000 = 450000$.<br>Doanh thu lớn nhất đạt được tại điểm $C(5000; 0)$. Tổng số chai tương ớt cần sản xuất là $5000 + 0 = 5000$ chai."}]}, {"noiDungChung": "Trong hệ tọa độ $Oxyz$, cho tứ diện $ABCD$ có các đỉnh $A({1};{3};-{2})$, $B({3};{2};-{4})$, $C({2};{1};{0})$, $D({3};{5};-{1})$.", "cauHoi": [{"question": "Gọi $M$ là trung điểm $BC$ thì góc $\\widehat{AMD}$ (làm tròn đến hàng đơn vị theo đơn vị độ) bằng", "choices": ["${45}^{\\circ}$", "${65}^{\\circ}$", "${30}^{\\circ}$", "${55}^{\\circ}$"], "correctIndex": 3, "explain": "Tọa độ trung điểm $M$ của $BC$ là $M\\left(\\dfrac{5}{2}; \\dfrac{3}{2}; -2\\right)$.<br>Các véc-tơ $\\vec{MA} = \\left(-\\dfrac{3}{2}; \\dfrac{3}{2}; 0\\right)$ và $\\vec{MD} = \\left(\\dfrac{1}{2}; \\dfrac{7}{2}; 1\\right)$.<br>Góc $\\widehat{AMD}$ được tính theo công thức vô hướng:  $$\\cos\\widehat{AMD} = \\dfrac{\\vec{MA}\\cdot\\vec{MD}}{|\\vec{MA}|\\cdot|\\vec{MD}|} = \\dfrac{-\\dfrac{3}{4} + \\dfrac{21}{4} + 0}{\\sqrt{\\dfrac{9}{4} + \\dfrac{9}{4}} \\cdot \\sqrt{\\dfrac{1}{4} + \\dfrac{49}{4} + 1}} = \\dfrac{\\dfrac{9}{2}}{\\dfrac{3\\sqrt{2}}{2} \\cdot \\dfrac{\\sqrt{51}}{2}} = \\dfrac{6}{\\sqrt{102}} \\approx 0{,}594.$$<br>Suy ra $\\widehat{AMD} \\approx 54{,}6^{\\circ} \\approx 55^{\\circ}$."}, {"question": "Gọi $A'$, $B'$, $C'$, $D'$ là hình chiếu của $A$, $B$, $C$, $D$ lên $Oxy$. Tứ giác tạo bởi các điểm đó là", "choices": ["Hình bình hành không hình thoi", "Hình thoi không hình chữ nhật", "Hình vuông", "Hình thang không cân"], "correctIndex": 3, "explain": "Tọa độ các hình chiếu trên mặt phẳng $Oxy$ là $A'(1; 3; 0)$, $B'(3; 2; 0)$, $C'(2; 1; 0)$, $D'(3; 5; 0)$.<br>Ta tính véc-tơ các cạnh để xét phương hướng:  $$\\vec{B'C'} = (-1; -1) \\quad \\text{và} \\quad \\vec{A'D'} = (2; 2) = -2\\vec{B'C'}.$$<br>Do $\\vec{A'D'}$ và $\\vec{B'C'}$ cùng phương nên $B'C' \\parallel A'D'$. Mặt khác, độ dài hai cạnh bên:  $$A'B' = \\sqrt{4 + 1} = \\sqrt{5} \\quad \\text{và} \\quad C'D' = \\sqrt{1 + 16} = \\sqrt{17} \\quad (A'B' \\neq C'D').$$<br>Tứ giác $A'B'C'D'$ có một cặp cạnh đối song song và độ dài hai cạnh bên không bằng nhau, vậy đây là hình thang không cân."}]}, {"noiDungChung": "Cho dãy số $(u_{n})$ biết $\\heva{&u_{1}={2026}\\\\&u_{n+1}=\\dfrac{{1}}{{2}}u_{n}}$", "cauHoi": [{"question": "Tính $S=u_{1}+u_{2}+\\dots+u_{n}+\\dots$ là", "choices": ["$S={3039}$", "$S={4052}$", "$S={2026}$", "$S={1013}$"], "correctIndex": 1, "explain": "Dãy số $(u_{n})$ là một cấp số nhân lùi vô hạn với số hạng đầu $u_{1}={2026}$ và công bội $q=\\dfrac{{1}}{{2}}$.<br>Tổng của cấp số nhân lùi vô hạn này là:  $$S=\\dfrac{u_{1}}{{1}-q}=\\dfrac{{2026}}{{1}-\\dfrac{{1}}{{2}}}={4052}$$"}, {"question": "Đặt $v_{n}=\\dfrac{u_{n}+1}{{3}u_{n}+{2}}$. Tính $L=\\lim\\limits_{n\\to+\\infty}\\left[\\dfrac{{2}}{n^{2}}({v}_{1}+{2}v_{2}+{3}v_{3}+\\dots+nv_{n})\\right]$", "choices": ["$\\dfrac{{1}}{{3}}$", "$\\dfrac{{1}}{{2}}$", "$+\\infty$", "${1}$"], "correctIndex": 1, "explain": "Ta có $u_n = 2026 \\cdot \\left(\\dfrac{1}{2}\\right)^{n-1}$, suy ra $\\lim\\limits_{n\\to+\\infty} u_n = 0$. Khi đó:  $$\\lim\\limits_{n\\to+\\infty} v_n = \\lim\\limits_{n\\to+\\infty} \\dfrac{u_n + 1}{3u_n + 2} = \\dfrac{0 + 1}{3(0) + 2} = \\dfrac{1}{2}$$  Vậy  $$L = \\lim\\limits_{n\\to+\\infty} \\dfrac{2(v_{1}+2v_{2}+\\dots+nv_{n})}{n^{2}} = \\lim\\limits_{n\\to+\\infty} \\dfrac{2nv_{n}}{n^{2}-(n-1)^{2}}$$  $$L = \\lim\\limits_{n\\to+\\infty} \\dfrac{2nv_{n}}{2n-1} = \\lim\\limits_{n\\to+\\infty} \\dfrac{2n \\cdot \\dfrac{1}{2}}{2n} = \\dfrac{1}{2}$$"}]}, {"noiDungChung": "Cho hình chóp $S.ABC$ có $SA\\perp(ABC)$. Biết $\\triangle ABC$ vuông cân tại $A$, đường trung tuyến $AD=a$. Góc giữa $SB$ và mặt phẳng đáy bằng ${45}^{\\circ}$.", "cauHoi": [{"question": "Góc tạo bởi $SB$ và đáy là:", "choices": ["$\\widehat{ASB}$", "$\\widehat{SBA}$", "$\\widehat{SAB}$", "$\\widehat{SAD}$"], "correctIndex": 1, "explain": "\\begin{center}  \\begin{tikzpicture}[scale=1, >=stealth]<br>\\coordinate (A) at (0,0);  \\coordinate (B) at (-1.5,-1.5);  \\coordinate (C) at (3.5,-1.5);  \\coordinate (D) at (1,-1.5);   \\coordinate (S) at (0,4); <br>\\draw[dashed] (A) -- (B);  \\draw[dashed] (A) -- (C);  \\draw[dashed] (A) -- (D);  \\draw[dashed] (S) -- (A);<br>\\draw[thick] (S) -- (B);  \\draw[thick] (S) -- (C);  \\draw[thick] (B) -- (C);<br>\\node[above] at (S) {$S$};  \\node[above left] at (A) {$A$};  \\node[below left] at (B) {$B$};  \\node[below right] at (C) {$C$};  \\node[below] at (D) {$D$};<br>\\draw (0,-0.2) -- (-0.2,-0.2) -- (-0.2,0);  \\end{tikzpicture}  \\end{center}  Vì $SA\\perp(ABC)$ nên hình chiếu của $S$ lên mặt phẳng $(ABC)$ là $A$. Do đó hình chiếu của $SB$ lên mặt phẳng $(ABC)$ là $AB$.<br>Suy ra góc giữa $SB$ và mặt phẳng đáy là góc giữa $SB$ và $AB$.<br>Vậy góc tạo bởi $SB$ và đáy là ${\\widehat{SBA}}$."}, {"question": "Số đo $\\widehat{SCD}$ bằng:", "choices": ["$45^{\\circ}$", "$60^{\\circ}$", "$90^{\\circ}$", "$30^{\\circ}$"], "correctIndex": 1, "explain": "Vì $\\triangle ABC$ vuông cân tại $A$ và $AD$ là trung tuyến ứng với cạnh huyền $BC$ nên $AD=BD=CD=a.$<br>Suy ra $AB=AC=a\\sqrt{2}.$<br>Từ câu trên, góc giữa $SB$ và đáy là $\\widehat{SBA}=45^{\\circ}$.<br>Vì $SA\\perp(ABC)$ nên $SA\\perp AB$. Xét tam giác vuông $SAB$ có  \\[\n\t\t\\widehat{SBA}=45^{\\circ}\n\t\t\\Rightarrow SA=AB=a\\sqrt{2}.\n\t\t\\]<br>Mặt khác,  \\[\n\t\tSD^2=\\sqrt{SA^2+AD^2}\n\t\t=\\sqrt{2a^2+a^2}=\\sqrt{3a^2}=a\\sqrt3,\n\t\t\\]  Do $CD\\perp AD$ và $CD\\perp SA$ nên $CD\\perp(SAD),$   suy ra $CD\\perp SD$. Do đó tam giác $SCD$ vuông tại $D$.<br>Ta có  \\[\n\t\t\\tan\\widehat{SCD}\n\t\t=\\frac{SD}{CD}\n\t\t=\\frac{a\\sqrt3}{a}\n\t\t=\\sqrt3.\n\t\t\\]  Vậy  \\[\n\t\t\\widehat{SCD}=60^{\\circ}.\n\t\t\\]"}, {"question": "Thể tích khối chóp $V_{S.ABC}$ là:", "choices": ["$\\dfrac{a^{3}\\sqrt{2}}{9}$", "$3a^{3}\\sqrt{2}$", "$a^{3}\\sqrt{2}$", "$\\dfrac{a^{3}\\sqrt{2}}{3}$"], "correctIndex": 3, "explain": "Từ giả thiết $\\triangle ABC$ vuông cân tại $A$ và $AD=a$ là trung tuyến ứng với cạnh huyền $BC$, ta có  \\[\n\t\tBC=2AD=2a.\n\t\t\\]  Do đó  \\[\n\t\tAB=AC=\\frac{BC}{\\sqrt2}=a\\sqrt2.\n\t\t\\]  Từ $\\widehat{SBA}=45^{\\circ}$ và $SA\\perp AB$, xét tam giác vuông $SAB$, ta có  \\[\n\t\tSA=AB=a\\sqrt2.\n\t\t\\]<br>Diện tích tam giác $ABC$ là  \\[\n\t\tS_{ABC}\n\t\t=\\frac12AB\\cdot AC\n\t\t=\\frac12(a\\sqrt2)^2\n\t\t=a^2.\n\t\t\\]<br>Vậy thể tích khối chóp $S.ABC$ là  \\[\n\t\tV_{S.ABC}\n\t\t=\\frac13SA\\cdot S_{ABC}\n\t\t=\\frac13(a\\sqrt2)\\cdot a^2\n\t\t={\\frac{a^3\\sqrt2}{3}}.\n\t\t\\]"}]}, {"noiDungChung": "Cho hàm số $f(x)=x^3-3x^2-9x+6$", "cauHoi": [{"question": "Hàm số nghịch biến trên khoảng?", "choices": ["$(-3;1)$", "$(0;3)$", "$(1;4)$", "$(-2;2)$"], "correctIndex": 1, "explain": "Ta có $f'(x)=3x^2-6x-9=3(x^2-2x-3)$.<br>$f'(x)<0\\Leftrightarrow -1<x<3$.<br>Do đó hàm số nghịch biến trên khoảng $(-1;3)$. Vì $(0;3)\\subset (-1;3)$ nên hàm số nghịch biến trên khoảng $(0;3)$."}, {"question": "Khoảng cách giữa các điểm cực trị của $f(x)$", "choices": ["$\\sqrt{438}$", "$\\sqrt{1040}$", "$\\sqrt{416}$", "$\\sqrt{728}$"], "correctIndex": 1, "explain": "Ta có $f'(x)=0\\Leftrightarrow\\hoac{&x=-1\\Rightarrow y=11\\\\&x=3\\Rightarrow y=-21.}$<br>Tọa độ các điểm cực trị là $A(-1;11)$ và $B(3;-21)$.<br>Khoảng cách giữa hai điểm cực trị là  $$AB=\\sqrt{(3-(-1))^2+(-21-11)^2}=\\sqrt{4^2+(-32)^2}=\\sqrt{16+1024}=\\sqrt{1040}=4\\sqrt{65}.$$"}, {"question": "Đường thẳng $y=m-3x$ cắt $f(x)$ tại $A$, $B$, $C$ sao cho $B$ là trung điểm $AC$. Giá trị $m$ nằm trong khoảng?", "choices": ["$(2;4)$", "$(-1;0)$", "$(0;2)$", "$(-3;1)$"], "correctIndex": 3, "explain": "Phương trình hoành độ giao điểm của hai đồ thị:  $$x^3-3x^2-9x+6=m-3x\\Leftrightarrow x^3-3x^2-6x+6-m=0\\quad (1)$$  Vì đường thẳng cắt đồ thị tại ba điểm $A$, $B$, $C$ sao cho $B$ là trung điểm của $AC$ nên $x_B$ phải là nghiệm của (1) và $x_B=\\dfrac{x_A+x_C}{2}$.<br>Theo định lý Vi-ét cho phương trình bậc ba: $x_A+x_B+x_C=3\\Leftrightarrow 3x_B=3\\Leftrightarrow x_B=1$.<br>Thay $x=1$ vào (1), ta được:  $$1^3-3(1)^2-6(1)+6-m=0\\Leftrightarrow 1-3-6+6-m=0\\Leftrightarrow m=-2.$$  Giá trị $m=-2$ nằm trong khoảng $(-3;1)$."}]}, {"noiDungChung": "Có ${3}$ hộp đựng. Hộp ${1}$ có ${1}$ thẻ xanh, ${1}$ đỏ, ${1}$ vàng. Hộp ${2}$ có ${1}$ thẻ xanh, ${1}$ đỏ. Hộp ${3}$ có ${1}$ vàng, ${1}$ đỏ. Lấy ngẫu nhiên từ mỗi hộp ${1}$ thẻ.", "cauHoi": [{"question": "Tính $n(\\Omega)$", "choices": ["${12}$", "${7}$", "${16}$", "${8}$"], "correctIndex": 0, "explain": "Số phần tử của không gian mẫu là số cách lấy ngẫu nhiên từ mỗi hộp ${1}$ thẻ:  $$n(\\Omega)={3}\\cdot{2}\\cdot{2}={12}$$"}, {"question": "Xác suất lấy được ít nhất ${1}$ thẻ đỏ", "choices": ["$\\dfrac{{3}}{{4}}$", "$\\dfrac{{2}}{{3}}$", "$\\dfrac{{5}}{{7}}$", "$\\dfrac{{5}}{{6}}$"], "correctIndex": 3, "explain": "Gọi $A$ là biến cố: \"Lấy được ít nhất ${1}$ thẻ đỏ\". Khi đó biến cố đối $\\overline{A}$ là: \"Không lấy được thẻ đỏ nào cả\" (tức là tất cả các thẻ lấy ra đều không phải màu đỏ).<br>- Hộp ${1}$ có ${3}$ thẻ (xanh, đỏ, vàng), số thẻ không đỏ là ${2}$ (xanh, vàng).<br>- Hộp ${2}$ có ${2}$ thẻ (xanh, đỏ), số thẻ không đỏ là ${1}$ (xanh).<br>- Hộp ${3}$ có ${2}$ thẻ (vàng, đỏ), số thẻ không đỏ là ${1}$ (vàng).<br>Số kết quả thuận lợi cho biến cố đối $\\overline{A}$ là: $n(\\overline{A})={2}\\cdot{1}\\cdot{1}={2}$.<br>Xác suất của biến cố đối là: $P(\\overline{A})=\\dfrac{{2}}{{12}}=\\dfrac{{1}}{{6}}$.<br>Xác suất để lấy được ít nhất ${1}$ thẻ đỏ là:  $$P(A)={1}-P(\\overline{A})={1}-\\dfrac{{1}}{{6}}=\\dfrac{{5}}{{6}}$$"}, {"question": "Xác suất lấy được ít nhất ${1}$ thẻ xanh là:", "choices": ["$\\dfrac{{2}}{{3}}$", "$\\dfrac{{5}}{{6}}$", "$\\dfrac{{5}}{{7}}$", "$\\dfrac{{1}}{{4}}$"], "correctIndex": 0, "explain": "Gọi $B$ là biến cố: \"Lấy được ít nhất ${1}$ thẻ xanh\". Biến cố đối $\\overline{B}$ là: \"Không lấy được thẻ xanh nào\" (tất cả thẻ lấy ra đều không phải màu xanh).<br>- Hộp ${1}$ có ${2}$ thẻ không xanh (đỏ, vàng).<br>- Hộp ${2}$ có ${1}$ thẻ không xanh (đỏ).<br>- Hộp ${3}$ có ${2}$ thẻ không xanh (vàng, đỏ).<br>Số kết quả thuận lợi cho biến cố đối $\\overline{B}$ là: $n(\\overline{B})={2}\\cdot{1}\\cdot{2}={4}$.<br>Xác suất của biến cố đối là: $P(\\overline{B})=\\dfrac{{4}}{{12}}=\\dfrac{{1}}{{3}}$.<br>Xác suất lấy được ít nhất ${1}$ thẻ xanh là:  $$P(B)={1}-P(\\overline{B})={1}-\\dfrac{{1}}{{3}}=\\dfrac{{2}}{{3}}$$"}]}, {"noiDungChung": "Trong mặt phẳng tọa độ $Oxy$, cho tam giác $ABC$ có các đỉnh $A(1; 5)$, $B(-3; 1)$, $C(5; 5)$.", "cauHoi": [{"question": "Gọi $I \\in Ox$ sao cho $(IA+IC)$ đạt giá trị nhỏ nhất. Tổng tọa độ của điểm $I$ là:", "choices": ["$2$", "$1$", "$0$", "$3$"], "correctIndex": 3, "explain": "Vì $A$ và $C$ nằm cùng phía đối với trục $Ox$, gọi $A'(1; -5)$ là điểm đối xứng của $A$ qua $Ox$. <br>Ta có $IA + IC = IA' + IC \\ge A'C$.<br>Dấu bằng xảy ra khi $I$ là giao điểm của đường thẳng $A'C$ với trục $Ox$.<br>Đường thẳng $A'C$ đi qua $C(5; 5)$ và có vectơ pháp tuyến $\\vec{n} = (5; -2)$ nên phương trình là:  $$5(x - 5) - 2(y - 5) = 0 \\iff 5x - 2y - 15 = 0.$$<br>Cho $y = 0 \\implies x = 3$, suy ra $I(3; 0)$. Vậy tổng tọa độ của điểm $I$ là $3 + 0 = 3$."}, {"question": "Gọi $H(a; b)$ là chân đường cao hạ từ $A$ xuống $BC$. Giá trị của $a + b$ là:", "choices": ["$1{,}8$", "$1$", "$5{,}2$", "$3$"], "correctIndex": 2, "explain": "Đường thẳng $BC$ đi qua $B(-3; 1)$ và $C(5; 5)$ có vectơ pháp tuyến $\\vec{n}_{BC} = (1; -2)$, phương trình:  $$x - 2y + 5 = 0.$$<br>Đường thẳng $AH$ đi qua $A(1; 5)$ và vuông góc với $BC$ nên nhận $\\vec{u}_{BC} = (2; 1)$ làm pháp tuyến, phương trình:  $$2(x - 1) + 1(y - 5) = 0 \\iff 2x + y - 7 = 0.$$<br>Tọa độ $H$ là nghiệm của hệ phương trình:  $$\\heva{&x - 2y = -5 <br>&2x + y = 7} \\iff \\heva{&x = 1{,}8 <br>&y = 3{,}4.}$$<br>Do đó $a + b = 1{,}8 + 3{,}4 = 5{,}2$."}, {"question": "Gọi $M$ là trung điểm $BC$ và $G$ là trọng tâm $\\triangle ABC$. Tính tích vô hướng $\\vec{AG} \\cdot \\vec{AM}$.", "choices": ["$-\\dfrac{16}{3}$", "$\\dfrac{8}{3}$", "$-\\dfrac{8}{3}$", "$\\dfrac{16}{3}$"], "correctIndex": 1, "explain": "Tọa độ trung điểm $M$ của $BC$ và trọng tâm $G$ của $\\triangle ABC$ là:  $$M(1; 3) \\quad \\text{và} \\quad G\\left(1; \\dfrac{11}{3}\\right).$$<br>Các véc-tơ $\\vec{AG}$ và $\\vec{AM}$:  $$\\vec{AG} = \\left(0; -\\dfrac{4}{3}\\right), \\quad \\vec{AM} = (0; -2).$$<br>Tích vô hướng:  $$\\vec{AG} \\cdot \\vec{AM} = 0 \\cdot 0 + \\left(-\\dfrac{4}{3}\\right) \\cdot (-2) = \\dfrac{8}{3}.$$"}]}, {"noiDungChung": "Có $9$ tay vợt $K, L, M, N, P, Q, R, S, T$ được xếp hạng từ $1$ (cao nhất) đến $9$ (thấp nhất) trên bảng xếp hạng Quốc gia. Biết rằng không có $2$ tay vợt nào xếp cùng hạng và các điều kiện xếp hạng được cho như sau:<br>- $M$ xếp hạng $1$ hoặc hạng $9$.  <br>- $K$ có thứ hạng cao hơn $L$ và $N$.  <br>- $L$ có thứ hạng cao hơn $Q$ và $R$.  <br>- $N$ có thứ hạng cao hơn $P$.  <br>- $Q$ có thứ hạng cao hơn $S$.  <br>- $S$ có thứ hạng cao hơn $T$.", "cauHoi": [{"question": "Danh sách nào dưới đây có thể là thứ tự xếp hạng của $9$ tay vợt từ hạng $1$ đến hạng $9$?", "choices": ["$L, R, K, N, P, Q, S, T, M$", "$K, L, N, P, Q, S, T, M, R$", "$K, R, N, P, L, Q, S, T, M$", "$M, K, L, N, Q, R, S, T, P$"], "correctIndex": 3, "explain": "Từ các điều kiện của đề bài, ta có chuỗi thứ bậc:   $$K > L > Q > S > T \\quad \\text{và} \\quad K > N > P.$$<br>Xét phương án đúng $M, K, L, N, Q, R, S, T, P$:<br>- $M$ xếp hạng $1$ (thỏa mãn điều kiện $M$ hạng $1$ hoặc $9$).  <br>- Thỏa mãn các quan hệ thứ bậc: $K$ đứng trước $L, N$; $L$ đứng trước $Q, R$; $N$ đứng trước $P$; $Q$ đứng trước $S$ và $S$ đứng trước $T$.<br>Các phương án còn lại vi phạm ít nhất một trong các điều kiện thứ bậc hoặc vị trí của $M$."}, {"question": "Nếu $P$ xếp hạng $3$, tập hợp tất cả các tay vợt có thể xếp hạng $6$ là:", "choices": ["$\\{Q, S\\}$", "$\\{Q, R\\}$", "$\\{Q, R, S\\}$", "$\\{R, S\\}$"], "correctIndex": 2, "explain": "Nếu $P$ xếp hạng $3$, do $N > P$ nên $N$ phải xếp hạng $2$ (hoặc cao hơn, nhưng $M$ có thể ở hạng $1$). <br>Khi đó nhóm các tay vợt đi sau $K, L, N, P$ phải phân bổ từ hạng $4$ đến hạng $9$. Dựa vào các chuỗi quan hệ $L > Q > S > T$ và $L > R$, các vị trí từ hạng $6$ hoàn toàn có thể linh hoạt thuộc về các tay vợt $Q, R,$ hoặc $S$ tùy thuộc vào cách chèn thứ tự của $R$."}, {"question": "Số tay vợt tối đa có thể xếp ở giữa $P$ và $Q$ là:", "choices": ["$4$", "$3$", "$2$", "$1$"], "correctIndex": 0, "explain": "Để số tay vợt ở giữa $P$ và $Q$ là lớn nhất, ta sắp xếp sao cho $P$ đứng ở vị trí cao (gần đầu bảng) và $Q$ đứng ở vị trí thấp (gần cuối bảng), đồng thời thỏa mãn toàn bộ các ràng buộc thứ bậc.<br>Một cấu hình khả thi đạt tối đa $4$ tay vợt đứng giữa $P$ và $Q$ (ví dụ thứ tự chứa chuỗi các vận động viên trung gian thỏa mãn các nhánh độc lập của $K, L, N, P, Q, S, T, R$ và $M$)."}]}, {"noiDungChung": "Có ${6}$ tình nguyện viên $G$, $H$, $K$, $L$, $M$, $N$ được chia thành ${3}$ đội ($D_1$, $D_2$, $D_3$), mỗi đội gồm ${2}$ người, trong đó có đúng ${1}$ người là đội trưởng. Biết rằng các điều kiện sau được thỏa mãn:<br>- $K$ ở cùng đội với $G$ hoặc $N$.  <br>- $H$ bắt buộc là đội trưởng (của đội mà $H$ tham gia).  <br>- $G$ hoặc $L$ (nhưng không phải cả hai) không là đội trưởng.", "cauHoi": [{"question": "Danh sách nào dưới đây có thể là phân công thành viên và đội trưởng của các đội?", "choices": ["Đ${1}$: $G$, $K$; Đ${2}$: $H$, $L$; Đ${3}$: $N$, $M$", "Đ${1}$: $L$, $G$; Đ${2}$: $K$, $M$; Đ${3}$: $H$, $N$", "Đ${1}$: $K$, $G$; Đ${2}$: $N$, $H$; Đ${3}$: $L$, $M$", "Đ${1}$: $G$, $K$; Đ${2}$: $L$, $M$; Đ${3}$: $H$, $N$"], "correctIndex": 2, "explain": "Kiểm tra phương án đúng:<br>- Đội ${1}$ gồm $K$ và $G$: thỏa mãn $K$ ở cùng đội với $G$.  <br>- Đội ${2}$ gồm $N$ và $H$, với $H$ là đội trưởng: thỏa mãn điều kiện $H$ làm đội trưởng.  <br>- Đội ${3}$ gồm $L$ và $M$.<br>Phân công này thỏa mãn toàn bộ các giả thiết của bài toán."}, {"question": "Nếu $H$ cùng đội với $L$ thì điều nào sau đây có thể đúng?", "choices": ["$G$ là đội trưởng", "$M$ cùng đội với $N$", "$K$ không là đội trưởng", "$N$ không là đội trưởng"], "correctIndex": 3, "explain": "Nếu $H$ và $L$ cùng đội, do $H$ là đội trưởng nên cặp $(H, L)$ hoàn thành đội thứ nhất. Các thành viên còn lại ($G, K, M, N$) phân bổ vào hai đội kia. Dựa trên các ràng buộc logic, trường hợp $N$ không giữ vai trò đội trưởng là hoàn toàn có thể xảy ra."}, {"question": "Nếu $M$ là đội trưởng thì hai người nào dưới đây phải ở cùng một đội?", "choices": ["$G$, $M$", "$L$, $N$", "$H$, $N$", "$K$, $N$"], "correctIndex": 3, "explain": "Nếu $M$ là đội trưởng, kết hợp với $H$ là đội trưởng, suy ra đội trưởng của đội thứ ba sẽ là $G$ hoặc $L$. Từ các ràng buộc về phân nhóm và vị trí, buộc $K$ và $N$ phải được xếp chung một đội để thỏa mãn điều kiện liên kết giữa $K$ và $N$."}]}, {"noiDungChung": "Tỷ lệ người lao động trong các ngành công nghiệp năm 2024 được thể hiện ở biểu đồ sau:<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1.1]\n\t\t\n\t\t\\def\\R{2}\n\t\t\n\t\t\n\t\t\n\t\t\\fill[blue!40] (0,0) -- (0:\\R) arc (0:90:\\R) -- cycle;\n\t\t\\draw[thick] (0,0) -- (0:\\R);\n\t\t\\draw[thick] (0,0) -- (90:\\R);\n\t\t\\node at (45:1.3) {${25}\\%$};\n\t\t\n\t\t\n\t\t\\fill[red!40] (0,0) -- (90:\\R) arc (90:198:\\R) -- cycle;\n\t\t\\draw[thick] (0,0) -- (198:\\R);\n\t\t\\node at (144:1.3) {${30}\\%$};\n\t\t\n\t\t\n\t\t\\fill[green!40] (0,0) -- (198:\\R) arc (198:270:\\R) -- cycle;\n\t\t\\draw[thick] (0,0) -- (270:\\R);\n\t\t\\node at (234:1.3) {${20}\\%$};\n\t\t\n\t\t\n\t\t\\fill[yellow!50] (0,0) -- (270:\\R) arc (270:360:\\R) -- cycle;\n\t\t\\node at (315:1.3) {${25}\\%$};\n\t\t\n\t\t\n\t\t\\draw[thick] (0,0) circle (\\R);\n\t\t\n\t\t\n\t\t\\begin{scope}[shift={(2.6, 1.2)}, font=\\small]\n\t\t\t\n\t\t\t\\draw[fill=blue!40] (0,0) rectangle (0.3,0.3); \n\t\t\t\\node[right] at (0.4,0.15) {Khai khoáng (${25}\\%$)};\n\t\t\t\n\t\t\t\n\t\t\t\\draw[fill=red!40] (0,-0.6) rectangle (0.3,-0.3); \n\t\t\t\\node[right] at (0.4,-0.45) {Chế biến chế tạo (${30}\\%$)};\n\t\t\t\n\t\t\t\n\t\t\t\\draw[fill=green!40] (0,-1.2) rectangle (0.3,-0.9); \n\t\t\t\\node[right] at (0.4,-1.05) {Cấp nước và HĐQL xử lý rác thải (${20}\\%$)};\n\t\t\t\n\t\t\t\n\t\t\t\\draw[fill=yellow!50] (0,-1.8) rectangle (0.3,-1.5); \n\t\t\t\\node[right] at (0.4,-1.65) {Nhóm ngành khác (${25}\\%$)};\n\t\t\\end{scope}\n\t\t\n\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Số lượng lao động trong chế biến chế tạo chiếm nhiều hơn bao nhiêu $\\%$ so với khai khoáng?", "choices": ["${15}\\%$", "${10}\\%$", "${5}\\%$", "${20}\\%$"], "correctIndex": 2, "explain": "Tỷ lệ lao động ngành chế biến chế tạo là $30\\%$, khai khoáng là $25\\%$.<br>Mức chênh lệch chiếm nhiều hơn là: $30\\% - 25\\% = 5\\%$."}, {"question": "Trong nhóm ngành khác, ngành sản xuất và phân phối điện chiếm ${20}\\%$. Tỷ lệ người lao động sản xuất \\& phân phối điện so với người lao động chế biến chế tạo là:", "choices": ["${1}:{3}$", "${1}:{6}$", "${1}:{5}$", "${1}:{2}$"], "correctIndex": 1, "explain": "Tỷ lệ người lao động sản xuất và phân phối điện so với tổng số lao động là:   $$20\\% \\times 25\\% = 5\\%.$$<br>Tỷ lệ so sánh giữa ngành này với chế biến chế tạo ($30\\%$) là:   $$\\dfrac{5\\%}{30\\%} = \\dfrac{1}{6} \\implies 1:6.$$"}, {"question": "Trong năm ${2015}$ do lao động ngành khai khoáng chuyển sang nên số lao động chế biến chế tạo tăng ${10}\\%$. Số lao động ngành khai khoáng giảm bao nhiêu $\\%$?", "choices": ["${6}\\%$", "${3}\\%$", "${12}\\%$", "${9}\\%$"], "correctIndex": 2, "explain": "Số lao động chế biến chế tạo ban đầu chiếm $30\\%$. Lượng tăng thêm chiếm:   $$30\\% \\times 10\\% = 3\\% \\text{ (so với tổng số lao động)}.$$<br>Lượng lao động này được chuyển từ ngành khai khoáng (ban đầu chiếm $25\\%$). Tỷ lệ phần trăm giảm của ngành khai khoáng là:   $$\\dfrac{3\\%}{25\\%} \\times 100\\% = 12\\%.$$"}]}, {"noiDungChung": "Cho bảng số liệu từ năm về chi phí và tỉ lệ lợi nhuận so với doanh thu của 2 công ty A và B từ năm $2014-2019$.<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Năm}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">\\parbox[c]{2.3cm}{\\centering<b>Chi phí Công ty A</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">(tỷ đồng)}}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">\\parbox[c]{2.7cm}{\\centering<b>Tỷ lệ lợi nhuận</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Công ty A (\\%)}}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">\\parbox[c]{2.3cm}{\\centering<b>Chi phí Công ty B</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">(tỷ đồng)}}</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">\\parbox[c]{2.7cm}{\\centering<b>Tỷ lệ lợi nhuận</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Công ty B (\\%)}}</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2014</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">16,5</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">15,4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">15,2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">20,1</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2015</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">17,2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">16,2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">17,3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">22,1</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2016</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">19,6</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">20,3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">16,3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">19,3</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2017</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">20,1</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">25,4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">18,5</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">25,5</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2018</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">22,4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">22,3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">20,2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">23,3</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2019</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">24,2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">23,4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">22,1</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">24,6</td></tr></table>", "cauHoi": [{"question": "Doanh thu của công ty $A$ năm ${2014}$:", "choices": ["${19}{,}{5}$ tỷ đồng", "${16}{,}{1}$ tỷ đồng", "${18}{,}{2}$ tỷ đồng", "${19}{,}{3}$ tỷ đồng"], "correctIndex": 0, "explain": "Tỷ lệ lợi nhuận trong bảng số liệu được tính trên cơ sở doanh thu: $\\text{Tỷ lệ lợi nhuận} = \\dfrac{\\text{Lợi nhuận}}{\\text{Doanh thu}} \\times 100\\%$.<br>Do đó, công thức tính doanh thu từ chi phí và tỷ lệ lợi nhuận là:  $$\\text{Doanh thu} = \\dfrac{\\text{Chi phí}}{1 - \\text{Tỷ lệ lợi nhuận}}$$  Áp dụng số liệu năm ${2014}$ của công ty $A$ (Chi phí $= {16}{,}{5}$ tỷ đồng, Tỷ lệ lợi nhuận $= {15}{,}{4}\\% = {0}{,}{154}$):  $$\\text{Doanh thu} = \\dfrac{{16}{,}{5}}{1 - {0}{,}{154}} = \\dfrac{{16}{,}{5}}{{0}{,}{846}} \\approx {19}{,}{50} \\text{ tỷ đồng)}$$"}, {"question": "Chênh lệch về lợi nhuận giữa công ty $A$ và $B$ năm ${2019}$:", "choices": ["${215}$ triệu đồng", "${182}$ triệu đồng", "${153}$ triệu đồng", "${100}$ triệu đồng"], "correctIndex": 1, "explain": "Lợi nhuận được tính bằng: $\\text{Lợi nhuận} = \\text{Doanh thu} \\times \\text{Tỷ lệ lợi nhuận} = \\dfrac{\\text{Chi phí}}{1 - \\text{Tỷ lệ}} \\times \\text{Tỷ lệ}$.<br>- Lợi nhuận công ty $A$ năm ${2019}$:  $$L_A = \\dfrac{{24}{,}{2} \\times {0}{,}{234}}{1 - {0}{,}{234}} = \\dfrac{{5}{,}{6628}}{{0}{,}{766}} \\approx {7}{,}{393} \\text{ (tỷ đồng)}$$  - Lợi nhuận công ty $B$ năm ${2019}$:  $$L_B = \\dfrac{{22}{,}{1} \\times {0}{,}{246}}{1 - {0}{,}{246}} = \\dfrac{{5}{,}{4366}}{{0}{,}{754}} \\approx {7}{,}{210} \\text{ (tỷ đồng)}$$  Chênh lệch lợi nhuận giữa hai công ty:  $$\\Delta L = |L_A - L_B| \\approx {7}{,}{393} - {7}{,}{210} = {0}{,}{183} \\text{ tỷ đồng} \\approx {182} \\text{ triệu đồng}$$"}, {"question": "Giai đoạn ${2014}-{2019}$ chi phí công ty $A$ xấp xỉ bao nhiêu phần trăm so với doanh thu:", "choices": ["${76}\\%$", "${79}\\%$", "${73}\\%$", "${82}\\%$"], "correctIndex": 1, "explain": "Tổng chi phí của công ty $A$ trong giai đoạn ${2014} - {2019}$:  $$\\sum \\text{Chi phí} = {16}{,}{5} + {17}{,}{2} + {19}{,}{6} + {20}{,}{1} + {22}{,}{4} + {24}{,}{2} = {120} \\text{ (tỷ đồng)}$$  Tổng doanh thu tương ứng trong giai đoạn (tính từ chi phí và tỷ lệ lợi nhuận từng năm):  $$\\sum \\text{Doanh thu} = \\dfrac{16,5}{1-0,154} + \\dfrac{17,2}{1-0,162} + \\dfrac{19,6}{1-0,203} + \\dfrac{20,1}{1-0,254} + \\dfrac{22,4}{1-0,223} + \\dfrac{24,2}{1-0,234} \\approx {151}{,}{9} \\text{ (tỷ đồng)}$$  Tỷ lệ phần trăm tổng chi phí so với tổng doanh thu:  $$\\text{Tỷ lệ} = \\dfrac{\\sum \\text{Chi phí}}{\\sum \\text{Doanh thu}} = \\dfrac{120}{{151}{,}{9}} \\times 100\\% \\approx {79}\\%$$"}]}]}];
